INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (4, 'AegisColar', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', 'Store or retrieve armor at press of a button; plates deploy via internal transporters.', 'The AegisColar is a sophisticated piece of gear designed to provide instant access to protective armor with the simple press of a button. This half-collar, worn around the back of the neck, can store an entire set of armor by breaking it down into individual plates and storing them within the collar itself. When needed, the collar swiftly reassembles and deploys the armor over the wearer’s body, providing immediate protection. The process is efficient, though it does produce a slight noise as the plates are fitted together during the assembly and disassembly.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (5, 'AeroJet Thruster', '["SciFi"]'::jsonb, '✨ Greater', 'M', '2-Enc', 'Atmospheric flight: 100 ft/Rnd vertical, MR(24) horizontal; 1 hr on Nova-Cores, recharges 1 min flight per 10 min.', 'The AeroJet Thruster is an advanced propulsion system worn as a backpack, designed specifically for atmospheric flight. Utilizing a combination of powerful turbofans and a minijet propulsion system, it enables the wearer to achieve vertical lift and horizontal movement. The pack is controlled through a pair of retractable arms equipped with joysticks, allowing for precise maneuverability in flight. However, its functionality is limited to environments with an atmosphere, rendering it ineffective in space. The pack is powered by Nova-Cores, providing up to one hour of continuous operation before needing to recharge. The Nova-Core recharges the pack at a rate of one minute of flight time for every ten minutes of downtime.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (6, 'Amulet of Dawn’s Radiance', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'A', '1-Enc', 'Magic✨ Atk (AOE 3sqR) vs undead; d8 radiant Dmg💥 and Weakened 1 rnd; Non-undead in AOE Heal+1 Vit❤️', 'Amulet of Dawn’s Radiance is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.340218+00:00') ON CONFLICT DO NOTHING;
