INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (12, 'Anti-Grav Harness', '["SciFi"]'::jsonb, '🍺 Minor', 'F', '1-Rnd', 'Enc(+150); eliminates 1 Wpn Enc(250) or less; Max MR lesser of (6 or MR(-1)); articulated arm mounts heavy weapon with buoyant support.', 'The Anti-Grav Harness is a sophisticated suspensor belt that provides unparalleled support and versatility for its wearer. This large metal ring, equipped with adjustable expansion slides, comfortably fits around the midsection of most beings. Once secured with eight inward-extending pins, the harness activates its anti-gravity field, allowing the user to hover effortlessly as they move. The harness has additional storage options provided by various hooks, fasteners, and compartments integrated into the belt’s design. Moreover, if the user’s armor is rigid, the harness can integrate directly with the armor. An articulated arm, which can mount a single heavy item like a cannon, extends from the belt and offers buoyant support, making even the heaviest weapons feel nearly weightless. The arm’s internal technology ensures that the user’s balance remains stable, despite the additional load. However, the harness does impose a movement restriction.
