INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (24, 'Blur Band', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-⚡', '[Dod/AR(✨+2)/(🧥)]; [Atk/Dmg(✨-1)/(✨+2)] [Awareness(👁️-1)]; [For(👁️)]^30 each Rnd or MR(3) until [For(👁️)]^50.', 'The Blur Band is a compact yet formidable piece of technology designed to alter the user’s physical presence within the surrounding environment. Resembling a heavy, wide, flat choker worn around the neck, it generates a powerful field of dimensional flux when activated. This field causes the wearer to phase in and out of the current dimension, displacing them slightly with each shift. The resulting effect makes the wearer appear as a blur, constantly shifting positions and making it exceedingly difficult for others to pinpoint their exact location. However, this dimensional instability also reduces the precision of the wearer’s own movements, complicating tasks that require fine motor control.
