INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (63, 'Cyber X-Ray Eye', '["SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', '[Awareness(👁️)] or skill to penetrate substance for viewing; requires existing cyber eye.', 'The Cyber X-Ray Eye is an advanced cybernetic implant designed to enhance an existing cyber eye, providing the user with the ability to see through various layers of material. This implant allows the user to penetrate surfaces, revealing hidden objects, spaces or things behind them. The depth of vision depends on the material’s density, with greater clarity through lighter substances such as cloth or thin walls, and more resistance when attempting to see through denser materials like stone or metal. This implant is particularly valuable for reconnaissance, security, and tactical operations, offering the wearer a significant advantage in environments where unseen obstacles or threats may lurk.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (64, 'Cyber-Legs, Speed', '["SciFi"]'::jsonb, '✨ Greater', 'F', '1-Rnd', 'MR(+2), [Motion Skills(🏃+1)]; Perm [Dod/AR(🏃+1)/(🧥)] with heat/crushing [Dod/AR(🏃+1)/(🧥+2)].', 'Cyber-Legs, Speed are a cutting-edge full-leg replacement designed for individuals seeking enhanced mobility and speed. These cybernetic limbs replace both legs entirely, including necessary reinforcements to the pelvic area to handle the increased weight and torque generated by the advanced mechanics. Constructed with a metal alloy core wrapped in a durable vulcanized rubber exterior, these legs are built to endure extreme conditions, including the heat from soft molten metal. The internal servos operate with remarkable quietness, ensuring smooth and efficient movement. Designed for speed, these cyber-legs significantly boost the wearer’s movement rate and agility, making them an ideal choice for those who require quick and nimble responses in high-stakes environments.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (65, 'Cyber-Legs, Strength', '["SciFi"]'::jsonb, '🪄 Lesser', 'F', '1-Rnd', 'Leg [Leg Str(💪+2)], Kick [Dmg(💪+1)]; Perm Max MR lesser of (8, or MR(-1)) heat/crushing [AR(🧥+3)].', 'The Cyber-Legs, Strength model is a powerful full-leg replacement designed for those who require enhanced strength and durability. These cybernetic limbs replace both legs entirely, incorporating enhancements to the pelvic area to support the increased weight and torque generated by their advanced mechanics. With a metal alloy core encased in a durable vulcanized rubber exterior, these legs are built to endure the harshest conditions, including exposure to soft molten metal. The internal servos are engineered to operate with near-silent efficiency, providing seamless and powerful movement. These cyber-legs significantly boost the wearer’s leg strength, allowing for immense power in activities such as shoulder lifts and leg presses, as well as delivering devastating kicks. However, the added bulk of these legs imposes a limit on the wearer’s movement rate, ensuring that the trade-off between strength and speed is carefully balanced.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (66, 'CyberGuards', '["SciFi"]'::jsonb, '🪄 Lesser', 'F', '3-Enc', '[AR(🧥+2)]^Blunt/Crush/Fall; stacks with OstealSteel for [AR(🧥+3)]', 'CyberGuards are a revolutionary cybernetic implant designed to enhance the body''s natural defense against blunt force trauma. These implants consist of thousands of nail-shaped shock absorbers that are meticulously embedded beneath the skin and anchored to the underlying bone structure. By distributing the impact of blunt forces more effectively than tissue alone, CyberGuards significantly reduce the damage from crushing, falling, or any blunt weapon strikes. The result is a system where the user might only experience a series of round, circular bruises instead of severe injuries. When combined with SteelOsteal enhancements, the protective benefits are amplified even further, making the wearer incredibly resilient to blunt trauma.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (67, 'D-Carbine', '["SciFi"]'::jsonb, '🪄 Lesser', 'A', '3-Enc', '[Atk/Dmg(👁️)/(👁️)] and the dimensional ball transforms into [d4] 1-pile of rubbel [Stuck(✨)]^💪, 2-flaming coals [d4] fire affliction, 3-sticky tar MR(/2) affliction, 4-grenade extra [Atk/Dmg(✨)/(✨)] 1r', 'The D-Carbine is a highly advanced and unpredictable weapon that uses dimensional technology to fire projectiles with transformative properties. This gun, while similar in design to a standard Blaster Carbine, differentiates itself by shooting two-inch diameter dimensional balls that, after traveling a short distance, transform into a variety of unpredictable objects or entities. These transformations can range from harmless ice cubes to deadly steel beams or even a fully operational combat mech. The randomness of each shot adds an element of chaos, making the D-Carbine both a powerful and a potentially dangerous tool in combat, especially when the results are unknown until the moment of impact.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (68, 'D-Shifter', '["Modern", "SciFi"]'::jsonb, '✨ Greater', 'P', '1-Enc', 'Phase out after Nish; act on Nish then vanish until next Rnd', 'The D-Shifter is an enigmatic and powerful artifact, believed to be a relic of the ancient and long-vanished Shinto race. This device grants its user the extraordinary ability to phase in and out of existence, effectively slipping into an alternate plane of reality. While active, the user remains on the battlefield, visible and vulnerable to observation and attack, but only until their initiative moment, or Nish. At this precise moment, the user can take any actions they desire, such as moving or attacking. Immediately after, they vanish, becoming completely untouchable and immune to all forms of attack for the remainder of the round. The D-Shifter’s power makes its wielder a formidable force in combat, particularly for those with a high initiative, as it allows them to strike and then disappear, avoiding any retaliation.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (69, 'D-Sizer', '["Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-⚡', 'Shrink or un-shrink eligible metal item (weapon or device no larger than Destron armor) to pawn size.', 'The D-Sizer is an ingenious and versatile set of disks that allows the user to manipulate the size of metal objects, reducing them to a fraction of their original dimensions while maintaining full functionality. The set includes two disks: one that bonds to the user and another that attaches to a metal item, such as a weapon or device no larger than Destron armor. With the D-Sizer, the user can shrink the bonded item down to the size of a chess pawn, drastically reducing its and weight to just a few ounces. This makes the D-Sizer an invaluable tool for smuggling large weapons or carrying bulky equipment without the usual physical burden. The disk worn by the user controls the size transformation, allowing for precise adjustments to any percentage of the original size. While the D-Sizer offers incredible convenience, expanding an item within a confined space comes with risks, as it can potentially damage weaker materials.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (70, 'D-Walker', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'P', '1-Enc', 'Shift to alternate dimension; move horizontally with no sensory input; reappear at new location on deactivation.', 'The D-Walker is a highly advanced dimensional transporter that allows the user to shift into another dimension, effectively removing themselves from the current plane of existence. While in this alternate dimension, the user is completely isolated from all sensory input—unable to see, hear, or sense anything around them. Despite this sensory deprivation, the user retains the ability to move freely in any horizontal direction. When the D-Walker is deactivated, the user reappears in their original dimension at a location corresponding to their movements while shifted. This device is invaluable for covert operations, allowing the user to walk through walls, escape dangerous situations, or even travel through the vacuum of space between ships. However, the D-Walker must be used with caution, as the user risks re-materializing inside solid objects, a perilous consequence determined by the Game Master based on the player’s verbal instructions.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (71, 'Decohesion Gun', '["SciFi"]'::jsonb, '🪄 Lesser', 'A', '1-Enc', '[Atk/Dmg(👁️)/(✨+1)] once hit, target is auto hit (justDmg); Wounds do nothing untill >🫀 then target implodes', 'The Decohesion Gun is a specialized energy weapon designed for precise and relentless elimination of high-armor, high-vitality targets. Unlike standard blaster carbines, the Decohesion Gun operates by firing a continuous stream of energy at a single target, requiring the wielder to maintain aim until the accumulated damage surpasses the target’s armor and vitality. Once this threshold is breached, the target undergoes a catastrophic mini implosion, effectively disintegrating in a gruesome spectacle reminiscent of a bug splatting against a windshield. This weapon is particularly effective against heavily armored foes, allowing for a tactical approach that gradually wears down even the toughest defenses. However, if the target manages to evade the beam or move out of range, the entire process must be restarted.
