INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (79, 'EnviroShield', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-⚡', '4" force shield: [Awareness(👁️)]^environmental/Explosions (poison, radiation, etc.); penalty MR(-2) & Agi(*0.5).', 'The EnviroShield is a highly advanced belt pack that, when activated, envelops the wearer in a four-inch thick, skin-tight force shield. This protective barrier is designed to block nearly all environmental hazards, including poison, toxins, diseases, radiation, and even the vacuum of space, providing the wearer with unparalleled protection in the most hostile environments. The shield also automatically seals over any bleeding wounds, stopping the bleeding with remarkable efficiency. Additionally, the EnviroShield comes equipped with a canister of compressed air. The canister automatically refills when exposed to breathable air, ensuring that the shield is always ready for the next use. However, while the shield is effective against environmental threats and small physical elements like sand and water, it does not protect against larger physical impacts or most energy weapons, making it less suitable for combat scenarios.
