INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (92, 'Ghost Mine', '["Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', 'Cloaks attached explosive at [Stealth(🏃)]^Awa; 3sq motion trigger beam.', 'The Ghost Mine is a deceptively simple yet incredibly effective device designed to turn any explosive into a deadly, cloaked trap. Despite its name, the Ghost Mine is not a mine in the traditional sense; instead, it is a small, button-like disc, only half an inch high and an inch in diameter. When attached to an explosive—be it a mine, grenade, plastic charge, or even a missile—the Ghost Mine cloaks the explosive with advanced stealth technology, rendering it invisible to the naked eye. This cloaking effect can conceal explosives up to the size of a six-foot missile, making it nearly impossible for enemies to detect. The Ghost Mine also projects a thin, invisible beam from its center, extending ten feet outward. Any motion that crosses this beam triggers the explosive, making it a perfect tool for setting up undetectable traps in strategic locations.
