INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (100, 'GravLift', '["SciFi"]'::jsonb, '🍺 Minor', 'F', '1-Rnd', 'On one weapon stock: Rng(*2), Draw Act(F)', 'The GravLift is an innovative attachment designed to significantly enhance the handling and performance of a weapon by reducing its weight and improving its maneuverability. This device consists of two thumb-sized cylinders that can be discreetly inserted into the stock of a weapon or attached to its side. Once activated, the GravLift’s micro pumps create a near-perfect vacuum within the cylinders, causing them to expand like balloons and generate a counteracting force that brings the weapon to true buoyancy. The onboard microcomputers continuously adjust for environmental factors and altitude, ensuring optimal performance in any situation. The result is a weapon that feels lighter, draws faster, and boasts an impressive increase in range, making it an invaluable tool for those who require precision and speed in combat.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (101, 'Grease Vial', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'A', '1-Enc', '2x2sq Slick Area; Magic✨ or target(s) are Prone', 'Grease Vial is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
