INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (103, 'GyroLock', '["Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', 'Atk(-10) Rnd 1; then cumulative Atk(+5) Rnd 2+ if target MR≤10. Rifle/cannon stabilizer.', 'The GyroLock is a precision stabilizer designed exclusively for rifles and cannons, offering unparalleled targeting accuracy by leveraging advanced gyroscopic technology. This small but powerful device clamps securely onto both sides of the weapon, providing a stabilizing force that dramatically improves aim after an initial adjustment period. When first activated, the GyroLock exerts a strong gyroscopic force that makes it difficult to move the weapon, resulting in an attack penalty as the user struggles to align with the desired target. However, after the first round, the stabilizer’s onboard computer takes over, locking onto the target and continuously tracking it as long as the target’s movement rate remains within specified limits. With each subsequent round that the user maintains focus on the same target, the GyroLock provides a cumulative aiming bonus, making it a formidable tool for snipers and heavy gunners who require precision and consistency in their shots.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (104, 'Hand-D', '["SciFi"]'::jsonb, '🪄 Lesser', 'F', '1-Rnd', 'Store or retrieve 1 item; instant draw/store Act(F) via mini-transporter band.', 'The Hand-D is an advanced piece of technology designed to make storing and retrieving objects as seamless and efficient as possible. This thin, flexible band wraps comfortably around the user’s hand, with small, easily accessible buttons embedded in the palm. The band houses a mini-transporter device capable of dematerializing a single object, storing its energy pattern within the band’s memory. With a simple press of the store button, the object vanishes from sight, its weight and reduced to zero. When the retrieve button is pressed, the object instantly rematerializes in the user’s hand, exactly as it was positioned when stored. This functionality allows for incredibly fast weapon draws and item swaps, turning what would be a cumbersome process into an effortless, nearly instantaneous action. The Hand-D is an invaluable tool for those who need to manage their gear efficiently, whether in combat or during exploration.
