INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (107, 'Higgs Band', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '2-Enc', '[Str(✨)]^Atk/Str or pulled to ground''s gravitational drop zone', 'The Higgs Band, a seemingly simple and unassuming device, is actually a highly advanced piece of technology designed to create a localized gravitational anomaly. Resembling a traditional oriental fan made of gray gauze, the Higgs Band measures about two feet long in its dormant state. When deployed, the fan telescopes to five feet in length and unfolds into a doughnut-shaped structure with a one-square center, extending outward to cover the surrounding area. Once activated, the band generates an incredibly strong gravitational field that exerts a force on any physical object that passes over it. This force is so intense that arrows, bullets, rocks, and even melee weapons are pulled straight down to its surface, rendering them harmless unless they can overcome the massive strength requirement. The gravitational pull does not follow conventional physics; instead of curving objects downwards, it forces them to drop vertically, regardless of their initial trajectory.
