INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (123, 'Kinetic War Band', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-Enc', 'Swung melee Dmg(+5), thrusting melee Dmg(+3).', 'The Kinetic War Band is a powerful bracer designed to enhance the force behind every melee strike by converting kinetic energy into additional impact. Worn securely around the forearm, this device harnesses the energy generated by swinging or thrusting a melee weapon, amplifying the force and translating it into increased damage. With each swing of a sword or axe, the Kinetic War Band channels the motion into a surge of additional power, significantly boosting the impact. When thrusting with weapons like spears or daggers, the band provides a similar, albeit slightly reduced, enhancement, making every strike more lethal. This augmentation turns even a simple melee attack into a devastating blow, giving the wearer a significant advantage in close combat situations.
