INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (138, 'Mech Core', '["SciFi"]'::jsonb, '✨ Greater', 'P', '1-⚡', 'Deploy 10'' Mech; MR(8), Blaster Rifle [Atk(👁️)][Dmg(👁️+1)], Power claw [Atk/Dmg(✨-1)/(✨+2)], [Dod/AR(✨-1)/(✨+1)] Vit [=(✨+1)]', 'The Mech Core is a deceptively small but incredibly powerful piece of technology designed to transform the battlefield in an instant. Resembling a softball-sized sphere, this device is unassuming at first glance, its surface smooth and metallic with subtle patterns etched across it. However, when dropped or thrown, the Mech Core activates upon impact, triggering a dimensional transporter that rapidly expands the sphere into a towering 10-foot-tall mechanized warrior. This imposing Mech is equipped with a dual laser rifle on one arm, capable of delivering precise, high-powered energy blasts, while the other arm features a large mechanical claw, perfect for gripping, crushing, or engaging in close-quarters melee combat. The Mech’s formidable presence and weaponry make it a devastating asset in any conflict, able to turn the tide of battle with its sheer power and versatility.
