INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (146, 'Moon Crown', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '3-Enc', 'Cone 90° medium range long; [Awareness(👁️)]^🫀 or blind for 1 Rnd.', 'The Moon Crown is an exquisite and powerful artifact, designed to radiate a stunning, heaven-like light that can illuminate vast distances. This tiara, delicate yet imposing, emits a light so intense that it resembles the brilliance of a sunrise, casting a 90-degree cone of illumination that stretches for miles in front of the wearer. When activated, the light is not just for show; in combat, it becomes a potent tool of disorientation. Any being that perceives the light within the visible spectrum must succeed in resisting its blinding effect, or else be rendered temporarily sightless for the remainder of the round. This effect covers a large area of effect, making the Moon Crown an ideal choice for disrupting enemy formations and gaining a tactical advantage. However, the blinding effect only lasts for one round, as the affected beings'' eyes quickly adjust to the intense brightness.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (147, 'Morphling', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', '[Pick Lock(✨+2)]^Dif to pick any keyed lock; [Clone(✨+2)] to duplicate sample (fingerprint, eye, etc.).', 'The Morphling is a unique and fascinating creature, often referred to as a "pet," though its abilities far surpass those of any ordinary animal. This small, amorphous being has the remarkable capacity to mold itself into the shape of any small hole or 3D object it encounters. Upon being placed near such a shape, the Morphling flows into it, perfectly conforming to its dimensions before returning to its original form. Trained by verbal commands, the Morphling can remember and replicate up to five different shapes, making it incredibly useful for tasks that require precision, such as mimicking a fingerprint, a key, or any other intricate form. Beyond its shape-shifting abilities, the Morphling possesses a unique skill for "playing" with locks, taking just a few moments to crack a combination or pick a lock, making it an invaluable companion for those who need to bypass physical security measures.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (148, 'MorphNet', '["SciFi"]'::jsonb, '🪄 Lesser', 'P', '3-Enc', 'Sk() Image Scanner until cumulative ^100; max 5 stored images; when active [Disguise(👁️+3)]^Awa to fool onlookers.', 'The MorphNet is an advanced and highly coveted piece of equipment, far surpassing the capabilities of standard disguise tools like the ImageWrap. This device, resembling a fishnet muscle shirt, is designed to stretch and conform to the body of nearly any user, from a human to a massive character. However, the true power of the MorphNet lies in its ability to molecularly transform the wearer’s outward appearance to perfectly mimic another being. By deploying a small, drone-like probe housed in a case attached to the shirt, the MorphNet can perform a thorough scan of a nearby target, capturing every detail of their physical form. Once the scan is complete, the MorphNet stretches over the wearer’s body like a hair net, seamlessly altering their appearance down to the finest details—growing wings, changing eye color, and even modifying vocal cords to match the target''s tone and pitch. While the transformation is primarily skin-deep, it is incredibly convincing, allowing the user to pass as their target with near-perfect accuracy.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (149, 'Mug of Endless Tea', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-⚡', 'Drink; Resist✨+2 on next roll this encounter', 'Mug of Endless Tea is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
