INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (153, 'Orb \- Luck', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-⚡', 'Restores [d5] Luck chits, not past max.', 'The Orb \- Luck is a mystical and rare artifact designed to restore the fortune of its wielder in times of need. This small, shimmering orb radiates with a soft, ethereal glow, hinting at the powerful magic contained within. Each use of the orb taps into this stored energy, restoring a portion of the user''s luck by replenishing lost luck boxes. The orb is capable of restoring d6 luck boxes with each use, up to the maximum limit allowed by the wielder''s abilities. However, this power is finite; the orb comes with only four uses, and once its magic is fully expended, the orb will shatter into a fine, sparkling dust, its purpose fulfilled and its power gone.
