INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (157, 'OstealSteel', '["SciFi"]'::jsonb, '🪄 Lesser', 'F', '1-Rnd', '[AR(🧥+2)]^Blunt; [Str(✨+3)] to break/sever limb.', 'The OstealSteel operation represents a pinnacle of cybernetic advancement, offering a comprehensive transformation of the body’s skeletal system into a near-indestructible titanium framework. This intricate procedure involves the infusion or replacement of every bone in the body with titanium filaments and plates, reinforcing joints and adjusting surrounding tissues to ensure a perfect fit. The operation is so complex that it requires the expertise of two cyber surgeons and a metallurgist, working together over the course of ten grueling hours. The results, however, are nothing short of extraordinary. The patient emerges with a skeleton that not only enhances their physical durability but also integrates seamlessly with any existing cybernetic enhancements such as joint locks, power joints, or CyberGuards, which are reconfigured and upgraded as part of the process.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (158, 'Pebble of Echoes', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-Enc', 'Throw; creates illusory footsteps; bag auto fills', 'Pebble of Echoes is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (159, 'PhaseStrider', '["SciFi"]'::jsonb, '🪄 Lesser', 'F', '1-Rnd', 'MR(*2); penalty 1 2nd Deg Wnd per Rnd (or per minute out of combat). Arm/leg bands; mini-teleport each step.', 'The PhaseStrider is an advanced set of cybernetic bands worn on the arms and legs, designed to significantly enhance the wearer’s movement speed by utilizing short-range teleportation. When activated, these bands enable the wearer to take a step and instantly teleport two paces ahead, effectively doubling their movement rate (MR). This rapid, blink-like movement allows for swift traversal of terrain, making the PhaseStrider an invaluable tool for those who need to cover ground quickly. However, the teleportations are too short and irregular to phase through solid objects, and are strictly limited to doubling the wearer''s stride.
