INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (165, 'PowerStiker', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'F', '2-Enc', 'Punch [Dmg(💪+1)]', 'The PowerStiker is an advanced pair of flexible metal gloves designed to significantly amplify the force of a punch through the use of built-in repulsor fields. These gloves, lightweight yet durable, are equipped with technology that activates upon impact, enhancing the force of each strike. When a punch is delivered, the repulsor fields generate an additional burst of energy, increasing the damage dealt by 1.5 times the normal amount. This makes the PowerStiker an ideal choice for those who rely on martial arts or hand-to-hand combat, turning each punch into a devastating blow capable of overwhelming opponents with sheer power. The gloves are also compatible with armor enhancement kits, further integrating their capabilities into a broader combat system.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (166, 'Q-Bond 2 Boots', '["Modern", "SciFi"]'::jsonb, '✨ Greater', 'P', '1-Enc', '[Str(💪)]^Dif to bond to any surface including ceiling; penalty MR(*0.5).', 'The Q-Bond 2 Boots are the next evolution of a widely popular footwear designed for extreme mobility and stability in challenging environments. Building on the capabilities of the original Q-Bond Boots, this second-generation model allows the wearer to adhere to virtually any surface with enhanced bonding strength, now improved to a formidable Strength. These boots are designed to lock and unlock with each step, allowing the user to walk on slippery surfaces, scale vertical walls, and even hang upside-down with ease. The main upgrade in the Q-Bond 2 Boots is the addition of a supportive energy field, akin to an invisible medical stretcher, that automatically adjusts to provide stability on steep slopes or walls. This innovation eliminates the need for additional checks when traversing such surfaces, relying solely on the boots'' impressive bonding strength.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (167, 'Q-Bond Boots', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-Enc', '[Str(💪)]^Dif to bond to any surface including vertical but not ceiling; penalty MR(*0.5).', 'The Q-Bond Boots are an innovative piece of footwear designed to provide unmatched stability and grip on a variety of surfaces, making them an essential tool for those operating in challenging environments. These boots utilize advanced bonding technology, allowing the wearer to adhere to any surface with a great bonding strength. The unique design of the Q-Bond Boots requires the user to lock and unlock the boots with each step, a feature that, while reducing the movement rate to half, ensures a secure hold on even the most slippery or treacherous surfaces. Whether walking on slick ground, scaling walls, or even hanging upside-down, the Q-Bond Boots offer unparalleled grip and versatility, though traversing vertical surfaces is most effective when the user can maintain a horizontal body position.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (168, 'Q-Cam', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '3-Enc', 'Capture object (max size suit of armor or large weapon); [Resist(✨)]^✨ if unwilling (e.g. held sword); non-living only', 'The Q-Cam is an extraordinary piece of technology, encased in a nearly transparent polymer block roughly the size of a typical red brick, with a small "DW" etched into one corner. This unusual device allows its user to capture and miniaturize a single object by simply pressing the block against the target, mimicking the action of taking a photograph. Once captured, the object is stored within the Q-Cam, suspended in stasis as if frozen in time, with no passage of time, no energy consumption, and no function. The captured object’s weight and are reduced to that of the Q-Cam itself, making it incredibly easy to carry even the largest of items, from vehicles to small buildings, depending on the Q-Cam''s quality.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (169, 'Quantum Anchor', '["SciFi"]'::jsonb, '🪄 Lesser', 'P', '2-Enc', 'Lock/unlock bar in space; Meta cost; unmovable at [Str(💪*5)]^Str/Force; failure = deactivation.', 'The Quantum Anchor is a mysterious and versatile piece of alien technology, resembling a sleek, shining gray metal bar approximately three feet in length. To activate the Quantum Anchor, the user simply grasps both ends and twists, engaging a powerful static field that locks the bar in place relative to the nearest large object—be it the ground, a vehicle, or a ship. Once activated, the Quantum Anchor becomes completely immovable, as if it character attached to an invisible, solid structure. This device can remain suspended in mid-air, defying gravity and maintaining its position with a formidable strength. The Quantum Anchor has been discovered throughout Known Space, especially in regions near Shinto Space, but its original purpose remains a mystery. However, its potential applications are nearly limitless, offering creative solutions for various scenarios.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (170, 'Quantum Gate', '["SciFi"]'::jsonb, '✨ Greater', 'P', '1-Enc', '[Awareness(👁️)]^Dif to link with another activated Quantum Gate within 1000 ft; 7'' portal between bars.', 'The Quantum Gate is a sophisticated and versatile device designed to create instant, stable portals between two locations, making it an invaluable tool for quick escapes, secure team links, or rapid transportation across short distances. The device consists of two square bars, each one foot long and two inches thick. When activated, the Quantum Gate bars extend to three feet in length and bond securely to the surface below using a Q-Bond field. Once activated, the Quantum Gate begins scanning for other active Quantum Gates within range. If another gate is detected and activated, a seven-foot tall wall of energy materializes above each bar, forming a portal that allows individuals to step through one gate and instantly emerge from the other.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (171, 'Quantum Leap', '["SciFi"]'::jsonb, '✨ Greater', 'P', '2-Enc', 'Teleport to stored location (max 3); max jump 100 miles; transport another at cost of 3 Uses; [Awareness(👁️)]^Dif for complex jump.', 'The Quantum Leap is an advanced belt designed to enable instantaneous transportation over vast distances, making it an invaluable tool for those who need to move quickly and discreetly. Worn around the user’s waist, this belt features a “lock” button that, when pressed, stores the exact position of the user’s feet in memory. The Quantum Leap can store up to three distinct locations, allowing the wearer to choose and erase any previous position as needed. When activated, the belt transports the user, along with any carried objects, up to 100 miles to the exact foot position previously locked, making it possible to reach distant locations such as a ship in low orbit. The technology is so precise that even locking onto a moving platform, like a vehicle or a strong person’s shoulders, allows for later teleportation back to that location—provided it remains within range.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (172, 'Quill of Sparks', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', 'Write script visible only with command word, glows in darkness', 'Quill of Sparks is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (173, 'Quill of Truth', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'AM', '1-⚡', 'Writes only truth (limited to one topic as per GM🔎)', 'Quill of Truth is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (174, 'Radiant [Weapon]', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'P', '1-⚡', 'Glows with Everlight (20 sq light with no shadows)', 'Radiant [Weapon] is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (175, 'Railgun', '["SciFi"]'::jsonb, '🪄 Lesser', 'A', '3-Enc', 'Dmg() reduces target AR (AR damaged until repaired); [Str(💪)]^Str to resist knockback.', 'The Railgun is a formidable weapon engineered for breaching walls, penetrating vehicle armor, and significantly weakening heavy armor. It fires a large, 10-pound metal sphere that, upon impact, sheds its jacket to release a super-dense disk and a collection of BB-sized pellets. The disk strikes with immense force, cracking the target’s surface, while the pellets penetrate and micro-detonate, causing further internal fractures. A concussive wave follows, ensuring that the target’s armor is severely compromised, leaving it damaged and vulnerable until repaired.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (176, 'RamJet Boots', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'M', '2-Enc', 'Jumps(**3); AoE [Dod/AR(🏃+2)/(🧥)].', 'The RamJet Boots are an advanced piece of footwear designed to enhance jumping capabilities by utilizing cutting-edge ram-jet technology. When the wearer jumps, these boots automatically activate, providing a powerful burst of air that significantly boosts the height and distance of the jump, allowing for impressive leaps over obstacles or across gaps. Additionally, the boots'' technology is smart enough to assist with avoiding area-of-effect attacks by enhancing the wearer’s ability to dodge. The user has control over the intensity of the boost, allowing them to reduce the effect to avoid overshooting their desired destination.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (177, 'RamJet Harness', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'M', '2-Enc', 'Jumps(**3); [Awareness(👁️)]^Dif for difficult landings; linking jumps "flight" up to 3 Rnds; reduce falling feet by [=(🏃+2)].', 'The RamJet Harness is a backpack-sized unit equipped with a powerful array of thrusters, designed to assist individuals in performing jumps that verge on short flights. When activated, the harness provides a significant boost to the wearer’s jump, multiplying their leap by three and allowing them to maintain this "flight" for up to three rounds. The harness is versatile enough to be activated during any type of jump, making it an ideal tool for crossing large gaps, reaching elevated positions, or executing complex aerial maneuvers. In emergency situations, the RamJet Harness can also be activated during a fall, deploying an intense burst of thrust to reduce the falling distance by a vertical jump equivalent to five times the user’s normal jump height.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (178, 'Rapier of Impure Alloy', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'A', '1-Enc', 'Atk+2 this rnd but Dmg💥-1', 'Rapier of Impure Alloy is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (179, 'Red Dot Scope', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'F', '1-⚡', 'This weapon''s Shot Atk(*1.5); doubles range; will stack with Dmg abilities (not with Atks)', 'The Red Dot Scope is a precision enhancement tool designed for ranged weapons, offering a significant advantage to marksmen by improving accuracy and extending the weapon''s effective range. This cylindrical attachment emits a thin, bright laser beam that clearly marks the impact point, allowing the user to line up their shots with pinpoint accuracy. The scope also features a stealth mode, where the laser beam becomes invisible to the naked eye, visible only through the scope’s sights. However, this stealth feature comes with a trade-off, as activating it imposes a penalty on the user’s initiative, making them slightly slower to act.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (180, 'Ring of the Serpent', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'P', '1-Enc', 'Poison aura; all foes in 3sqR Rolls-2 vs Resist✨', 'Ring of the Serpent is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (181, 'Ring of Two Stars', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'A', '1-Enc', 'Magic✨ Atk for d12 Dmg💥 vs 2 targets', 'Ring of Two Stars is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (182, 'Rune Flask of Blackaxe Ale', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1', 'Drink; Heal self 1 Vit❤️', 'The Rune Flask of Blackaxe Ale is a sturdy, iron-bound glass container adorned with ancient runes that shimmer with a warm, amber glow. The ale inside is thick and dark, with a heady aroma of hops and a hint of mystical energy.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (183, 'Runed [Weapon]', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'A', '1-Enc', 'On hit;; Runes explode for additional +4 Dmg💥', 'Runed [Weapon] is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
