INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (186, 'Scepter of Storms', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'A', '1-⚡', 'Magic✨ Atk; d✨ lightning Dmg💥 in 4x4sq', 'Scepter of Storms is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (187, 'Scout Swarm', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '2-Enc', 'Scouts Stealth = [Stealth(🏃)]^Awa; MR(5) max short to medium range from host; [Awareness(👁️)]^Dif vs hidden/invisible life.', 'The Scout Swarm is a remarkable and discreet surveillance tool, consisting of a colony of approximately 1,000 tiny, translucent creatures, each only a few millimeters across. When released, the swarm spreads out to cover a wide area, scouting up to a maximum number of squares around the user. These tiny scouts are difficult to detect, their near-invisible bodies blending seamlessly with the environment. The swarm''s primary function is to locate sentient life within their scouting range and telepathically report the location and rough size of the individual(s) back to the user. This makes them an invaluable asset for gathering intelligence or maintaining vigilance in potentially dangerous situations.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (188, 'Scroll of the Commet', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'A', '1-⚡', 'Magic✨Atk and Dmg💥 both with Advantage', 'Scroll of the Commet is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (189, 'Shadow Thread', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'F', '2', 'Stich a normal item to your clothing; Will always reattach as if hooked', 'Shadow Thread is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (190, 'ShadowBand', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'F', '1-Rnd', 'Radius of full daylight (any size up to 3r); no light beyond radius; no shadows within.', 'The ShadowBand is an elegant and deceptively powerful piece of gear, designed as a smooth golden ring that offers a unique control over light. When activated, the ring generates a field of light, within its radius, as bright as full daylight. What makes this light extraordinary is its ability to completely eliminate shadows within its range, allowing the light to permeate even the smallest openings. The wearer can adjust both the radius and the brightness of the light, tailoring it to their specific needs. However, the true brilliance of the ShadowBand lies in its stealth capability: the light stops abruptly at the edge of the radius, leaving the environment beyond it in its natural state, whether that be darkness or dim lighting.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (191, 'Shard of Echo', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'M', '1-Rnd', 'Always Perfectly Repeats last 3 phrases heard', 'Shard of Echo is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
