INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (195, 'Shimmer Veil [Armor]', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'P', '1-Enc', 'Become Invisible for 1 rnd', 'Shimmer Veil [Armor] is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (196, 'Shoes of Silence', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'M', '1-Enc', 'Motion🏃 Stealth with Advantage', 'The Shoes of Silence are crafted from supple, dark leather with a seamless, rubber-like soles that absorb sound. Their surface is etched with faint, glowing runes that pulse softly with each step, ensuring the wearer moves without a whisper.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (197, 'SlingGauntlets', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'M', '2-Enc', '15 sq (75 ft) strand; Q-Bond [Str(💪)]; reel at MR 15; [Acrobatics(🏃+1)].', 'The SlingGauntlets are advanced technological gloves designed to provide rapid grappling-like movement, reminiscent of a certain comic book hero. These gloves bond securely to the wearer’s hands, ensuring no slippage during use. Each glove contains a spider-thin polymer strand capable of being fired for many feet, with a tip capped by a Q-Bond pad that automatically bonds to any surface with a large strength, without the need for a roll during normal use. The gloves can rapidly reel in the strands, allowing for swift movement or quick retrieval. Each glove holds twice its feet range of strand, providing enough material to account for potential damage or loss.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (198, 'Smoke Bomb of Shrouding', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-⚡', 'Create 3x3sq smoke cloud; all Stealth rolls in area with Advantage', 'Smoke Bomb of Shrouding is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (199, 'Smoke Bomb Satchel', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'A', '1-Enc', 'Throw 1 bomb; create 3x3sq smoke cloud; foes inside suffer Disadvantage on Atk & Dodge🏃 for 1 rnd', 'The Smoke Bomb Satchel is a leather pouch lined with reinforced fabric, holding multiple smoke bombs. When a bomb is thrown, it explodes into a thick cloud of smoke that disorients enemies, making it difficult for them to aim or dodge effectively.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (200, 'Smoke Pellet', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', 'Creates smoke cloud; immedite Dodge with Advantage', 'A small, brass-colored pellet that emits a dense, swirling cloud of ink-black smoke when activated. The smoke is thick and persistent, obscuring vision and creating a momentary shield of concealment.', NULL, '2026-08-13T21:26:28.441265+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (201, 'Soap Bubble Wand', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'A', '1-Enc', 'Distract 1 foe; Magic✨ or target loses all actions this round', 'The Soap Bubble Wand is a slender, ornate wand with a handle wrapped in soft, velvet-like material. When activated, it produces a cascade of iridescent bubbles that distract foes, momentarily confusing them and leaving them vulnerable.', NULL, '2026-08-13T21:26:28.538529+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (202, 'Sonic Marble', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'A', '1-Enc', 'Throw; Magic✨ or target is Dazed; Must be retrieved', 'The Sonic Marble is a smooth, glass-like sphere that vibrates with an almost imperceptible hum. When thrown, it emits a burst of sound that stuns the target, leaving them momentarily dazed and disoriented.', NULL, '2026-08-13T21:26:28.538529+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (203, 'Soulpiercer [Weapon]', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'A', '1-Enc', 'On hit; Bypasses AR🧥', 'The Soulpiercer is a weapon of exquisite craftsmanship, featuring a blade forged from a rare, silvery metal that seems to drink in light. Its edge is razor-sharp and designed to pierce through even the toughest of armors.', NULL, '2026-08-13T21:26:28.538529+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (204, 'Spark Key', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-⚡', 'Touch to unlock normal locks up to Dif15', 'The Spark Key is a small, intricately designed key with a metallic surface that glints with a faint, electric sheen. It is capable of unlocking even the most complex of locks, making it an invaluable tool for any adventurer.', NULL, '2026-08-13T21:26:28.538529+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (205, 'Spear of the Horizon', '["Medieval", "Modern", "SciFi"]'::jsonb, '✨ Greater', 'A', '1-⚡', 'Ranged strike; auto-hits 1 target in sight; Dmg💥 d🏃+8', 'Spear of the Horizon is engineered with high-durability composite materials for reliable field operations.', NULL, '2026-08-13T21:26:28.538529+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (206, 'Spearof Phalanx', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-Enc', 'On hit; Might💪pushes target 1sq. If ally has or will likely Atk target this rnd, both Dmg💥+1', 'The Spearof Phalanx is a finely crafted spear with a reinforced wooden shaft and a sharp, steel-tipped head. The spear''s design emphasizes both thrusting power and the ability to push opponents back, making it a formidable weapon in close combat.', NULL, '2026-08-13T21:26:28.538529+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (207, 'SpectraGuard', '["Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-⚡', 'AR(*1.5); cloaks at [Stealth(🏃)]^Awa; shield drops for Rnd if shooting then reactivates.', 'The SpectraGuard is a sophisticated personal defense device designed to generate a protective shield around its user while also providing a cloaking effect. When activated, the SpectraGuard projects a shield that significantly enhances the user’s protection against incoming attacks, while simultaneously cloaking the user, making them nearly invisible to onlookers. The shield is sensitive to large energy expenditures, such as firing a weapon, which temporarily disables the shield before it reactivates. The SpectraGuard is powered by an energy cell that sustains its functions for a limited duration and can recharge itself fully within a short period.
