INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (215, 'Stim +10 Vit', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', 'Vit(+10)', 'The Stim \- Vit is a powerful medical stimulant designed to temporarily enhance a user’s vitality, making it an essential tool for those facing prolonged or intense physical challenges. Upon administration, the stim boosts the user’s maximum vitality, allowing them to endure more damage and push their limits for an extended period. This increase in vitality provides a crucial buffer in combat or other high-stress situations, enabling the user to sustain greater injuries without succumbing. However, it is important to note that Vit Stims do not stack with one another, ensuring that only a single dose can be active at any given time.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (216, 'Stim +3 MR', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '2-Enc', 'MR(+3)', 'The Stim \- MR is a specialized stimulant designed to enhance a user’s movement rate, making it an invaluable asset for those who need to move quickly over extended periods. Upon injection, the stim provides a significant boost to the user’s movement rate, allowing them to cover more ground at a faster pace. This makes the Stim \- MR ideal for situations that require rapid deployment, evasive maneuvers, or quick retreats. However, the stim’s effects are carefully regulated; it does not stack with other MR Stims, and if combined with non-stim MR buffs or gear, the boost is reduced to ensure safe and balanced performance.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (217, 'Stim Greater Healing', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-Enc', '[Heal(✨-1)] 1st Deg Wnds OR [Heal(✨-2)] 2nd Deg Wnds OR [Heal(✨/15)] 3rd Deg Wnds', 'The Stim \- Greater Healing is a potent medical stimulant designed to rapidly cure significant injuries, offering a powerful solution in moments of critical need. With each use, the stim allows the user to choose from one of several healing options: it can fully heal a large number of minor wounds, address a substantial portion of moderate wounds, or treat severe injuries. This versatility makes it an essential tool for field medics and those in dangerous situations where immediate and targeted healing is necessary. However, caution must be exercised, as administering more than one healing stim (of any kind) during a single event carries the risk of overloading the target''s system, potentially causing them to fall unconscious.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (218, 'Stim Light Healing', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', '[Heal(✨-2)] 1st Deg Wnds', 'The Stim \- Cure is a powerful medical stimulant designed to combat even the most dangerous poisons and diseases, offering a critical lifeline in dire situations. Upon administration, the stim works rapidly to neutralize toxins or infections, using an advanced formula that operates with a high degree of efficacy. The stim is incredibly precise, with each dose designed for a single-use per target per incident, ensuring that multiple attempts are not possible, emphasizing the importance of timely and accurate application. Additionally, if administered to a recently deceased target within a short window of time, the Stim \- Cure offers a unique chance to revive the individual, triggering an immediate Death Check that significantly increases the odds of survival.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (219, 'Stim ⚔️ Action', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'M', '1-Enc', 'Provides an extra ⚔️(Attack Action)', 'The Stim \- Action is a potent stimulant designed to enhance a user’s performance by providing an additional action each round for a limited duration. Upon injection, the stim rapidly increases the user’s ability to react and perform tasks, granting an extra burst of energy that lasts for a few crucial moments. This makes it an invaluable tool in high-pressure situations where every second counts. However, due to its powerful effects, only one action stim can be used per event, ensuring that the user does not overextend themselves or risk adverse effects from overstimulation.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (220, 'Stim ✋ Action', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'M', '1-Enc', 'Provides an extra ✋(Partial Action)', 'The Stim \- Action is a potent stimulant designed to enhance a user’s performance by providing an additional action each round for a limited duration. Upon injection, the stim rapidly increases the user’s ability to react and perform tasks, granting an extra burst of energy that lasts for a few crucial moments. This makes it an invaluable tool in high-pressure situations where every second counts. However, due to its powerful effects, only one action stim can be used per event, ensuring that the user does not overextend themselves or risk adverse effects from overstimulation.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (221, 'Stim 🏃 Buff', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', '[Skills(🏃+2)]', 'The Stim \- Atr Buff is a specialized stimulant designed to temporarily enhance one of the user’s key attributes, providing a significant boost in performance for a short duration. Upon injection, the stim amplifies the chosen attribute—whether it be Agility, Arcane, Awareness, Fortitude, Mental, Social, Strength, Luck, or Vitality—by enhancing the user''s skill checks related to that attribute. While the effects are potent, they are focused solely on improving skill rolls and do not influence other aspects of the attribute, such as increasing maximum vitality or movement rate. Multiple stims can be used simultaneously to boost different attributes, but no single attribute can benefit from more than one stim at a time.
INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (222, 'Stim 👁️ Buff', '["Medieval", "Modern", "SciFi"]'::jsonb, '🍺 Minor', 'P', '1-Enc', '[Skills(👁️+2)]', 'The Stim \- Atr Buff is a specialized stimulant designed to temporarily enhance one of the user’s key attributes, providing a significant boost in performance for a short duration. Upon injection, the stim amplifies the chosen attribute—whether it be Agility, Arcane, Awareness, Fortitude, Mental, Social, Strength, Luck, or Vitality—by enhancing the user''s skill checks related to that attribute. While the effects are potent, they are focused solely on improving skill rolls and do not influence other aspects of the attribute, such as increasing maximum vitality or movement rate. Multiple stims can be used simultaneously to boost different attributes, but no single attribute can benefit from more than one stim at a time.
