INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (233, 'Temporal Spray', '["Modern", "SciFi"]'::jsonb, '🍺 Minor', 'M', '2-Enc', 'Spray [Atk(🏃)] on opponent; Allies gan Adv vs all of target''s time-sensitive stats (Dod, Blk, Atk, etc.)', 'The Temporal Spray is an innovative and highly specialized tool, designed to manipulate the perception of time through a unique application of thin, glass-like film. Each canister, resembling a small spray can, contains a material that when applied to a surface—such as a window, helmet, or camera lens—creates a time delay in the transmission of light. This delay causes everything viewed through the treated surface to appear as if it character happening in the past. The real ingenuity lies in the material’s ability to stretch time; initially, the images appear in slow motion, gradually reaching the full delay, and then continue at normal speed but with the specified delay in effect. Temporal Spray is a valuable asset for strategic planning and misdirection.
