INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (236, 'Thumper', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'F', '1-⚡', 'Heals all Wnds and ailments on Nish 0 of next Rnd; until then user spasms (no MR or actions)', 'The Thumper is a powerful and mysterious healing device, taking the form of a large, crimson pill filled with a viscous substance teeming with microscopic nanites. Manufactured by a secretive Company that guards the formula closely, the Thumper is designed to provide rapid, near-instantaneous healing by utilizing these nanites. Once ingested, the nanites swiftly circulate through the user’s body, seeking out damaged tissues and injecting them with the healing fluid. They then work meticulously, using their small claws to remove dead tissue and repair the damage. The result is nothing short of miraculous, with all wounds healed and the user fully revived by the end of the next round following ingestion.
