INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (255, 'Wall of Thune', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '1-⚡', 'wide, tall wall high x short range wide wall; non-destructive; [Str(💪+4)]^Str to move; Sk2 = [AR(💪+6)], Vit[=(🫀-1)]', 'The Wall of Thune is a remarkable piece of ancient technology housed within a metallic ball no larger than a baseball. When thrown, this compact device activates upon impact with a surface, unfolding to reveal a massive granite wall, three feet thick and up to twenty feet high and wide. The wall materializes in an instant, forming a formidable barrier of old castle-style blocks that can withstand significant force. Its non-destructive nature ensures that it will only manifest on relatively flat surfaces, avoiding damage to surrounding objects. However, the wall''s immense weight of 100 tons can still cause indirect harm, such as collapsing a weak structure beneath it. The wall can be retracted by tapping it three times with a unique pattern, though any block not in contact with others when the wall is retrieved will be lost.
