INSERT INTO public."relics" ("id", "name", "genres", "category", "action", "usage", "effect", "notes", "pic", "created_at") VALUES (262, 'Willstone', '["Medieval", "Modern", "SciFi"]'::jsonb, '🪄 Lesser', 'P', '3-Enc', 'When held: [Domination(👁️)]^🫀; Perm Men(*2) while on person.', 'The Willstone is a powerful artifact known for its ability to fortify the mental resilience of its bearer. When carried as part of one''s gear, the Willstone enhances the user’s Mental attribute, making it an invaluable tool for resisting mental assaults and maintaining focus in the most trying circumstances. Additionally, when the stone is held in hand, it grants the user a formidable Domination skill, allowing them to exert their will over others with exceptional potency. This combination of passive and active abilities makes the Willstone a sought-after item for those who need to strengthen their mind and impose their will in critical moments.
