INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (2, 'Aether Sword', 'Melee', '💪 8', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Aether Sword
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (3, 'Assault Slugger', 'Shot', '👁️ 8', NULL, '5g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Assault Slugger is a heavy automatic weapon that fires metal slugs designed to detonate on impact within the target rather than in an area. It is bulky and functions like a large machine gun. When set to full auto, damage increases significantly, but the operator suffers an attack penalty and consumes four rounds per attack.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (4, 'Axe', 'Melee', '💪 8', '16', '2g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Axe is a classic two-handed melee weapon built for raw impact and intimidation. Battle-axes feature a large double head mounted on a stout shaft, delivering devastating chops and cleaving strikes. They remain a staple among frontline fighters and warrior traditions across many worlds.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (5, 'Bastard Sword', 'Melee', '💪 10', '20', '6g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bastard Sword is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (6, 'Battleaxe', 'Melee', '💪 8', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Battleaxe is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (7, 'Beak-Mace', 'Melee', '💪 8', '16', '2g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Beak-Mace is a distinctive melee weapon consisting of a knobby striking ball and a long, beak-like metal spike. The beak can be loaded with up to ten doses of poison, and when the user chooses to inject, a successful hit delivers the dose; the victim suffers poison effects if the attack causes wounding damage. Delivering a poison injection requires a declared attack and incurs a penalty to the attack roll.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (8, 'Bio-Forge Gauntlet', 'Melee', '💪 8', '16', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bio-Forge Gauntlet
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (9, 'Bio-Spitter', 'Shot', '👁️ 8', NULL, '6g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Bio-Spitter filters impurities and waste from its host’s body, and as a weapon, for it can launch the resulting biochemical compounds at an enemy. Compounds are stored in soft egg sacs—one egg per hour—and the spitter holds up to ten. A hit is caustic and potentially deadly.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (10, 'Bio-Vine Whip', 'Melee', '💪 6', NULL, '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bio-Vine Whip
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (11, 'Blaster Cannon', 'Shot', '👁️12', NULL, '12g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Blaster Cannon is a heavy, auto-firing energy weapon built for sustained suppression and area denial. It is typically slung from a shoulder strap and fired from the hip, allowing the operator to lay down a continuous stream of fire while maintaining mobility.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (12, 'Blaster Carbine', 'Shot', '👁️ 10', NULL, '5g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Blaster Carbine bridges the gap between sidearm and rifle, offering greater damage and range than a pistol at the cost of size and ease of concealment. It is widely used by irregulars, raiders, and special operations units who need compact firepower without the bulk of a full rifle.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (13, 'Blaster Pistol', 'Shot', '👁️ 6', NULL, '3g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Blaster Pistol is the standard sidearm for military officers, law enforcement, and starship personnel. Compact and relatively easy to conceal, it provides a reliable backup when heavier weapons are impractical or unavailable.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (14, 'Blaster Rifle', 'Shot', '👁️ 10', NULL, '6g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Blaster Rifle is the standard infantry long arm in most military and paramilitary forces. It requires two hands to fire effectively, though the trigger grip can be rotated for underhand or overhand firing in tight spaces. The rifle’s larger emitter produces a bigger, more ovoid energy charge than pistols or carbines, increasing both damage and effective range.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (15, 'Bloodblade', 'Melee', '💪 8', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bloodblade
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (16, 'Blowgun', 'Shot', '👁️ 4', NULL, '1g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Blowgun is one of the simplest missile weapons in use: a long hollow tube that propels a small dart by breath alone. It is common on low-tech and frontier worlds, where its silence and portability make it a favored tool for hunters and covert operatives. Unenhanced darts rarely cause serious injury, but poison-tipped darts turn the blowgun into a deadly stealth weapon.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (17, 'Bormaul Eggs', 'Hurled', '🏃 8', NULL, '2g', '2026-08-13T21:26:27.294759+00:00', '🏃', '🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bormaul Eggs can be launched from bio-spitters or thrown by hand. Each egg contains a small crustacean (a bormaul). Normally tough and leathery, death eggs grow fragile when thrown, and break upon impact. When they hit, no damage results (often lulling opponent’s into a false sense of security).
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (18, 'Botanic Grenades', 'Hurled', '🏃 12', NULL, '2g', '2026-08-13T21:26:27.294759+00:00', '🏃', '🏃', '["Modern", "SciFi"]'::jsonb, 'Botanic Grenades
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (19, 'Bow', 'Shot', '👁️ 8', NULL, '2g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Bow is a timeless missile weapon still widely used on primitive worlds and by scouts, hunters, and covert operatives. This model stands about four feet unstrung with a draw weight of roughly forty pounds, balancing portability with enough power to pierce armor at short to medium range. Poison-tipped or specially treated arrows make it a potent stealth and assassination tool.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (20, 'Bow (Long)', 'Shot', '👁️ 6', 'n/a', '3g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bow (Long) is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (21, 'Brawl', 'Melee', '💪 4', 'n/a', 'X', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Kick, Punch, Bite, GTH, Tail, Tacklet, etc.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (22, 'Caustic Spitter', 'Shot', '💪 12', '24', '7g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Caustic Spitter is a living weapon harvested from a knotted plant structure. It is formed when certain beetles infest trees and attract nesting spiders. The spider builds a cocoon and uses secretions to lure beetles in, then stores them and its waste.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (23, 'Chain Whip', 'Melee', '💪 4', '8', '2g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Chain Whip is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (24, 'Channel Crystals', 'Hurled', '🏃 8', NULL, '3g', '2026-08-13T21:26:27.294759+00:00', '🏃', '🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Channel Crystals are clear, multi-faceted gems with a hollow center, roughly the size of a small grenade.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (25, 'Clawed Gauntlets', 'Melee', '💪 8', '16', '2g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Clawed Gauntlets
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (26, 'Claymore', 'Melee', '💪 10', '20', '6g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Claymore is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (27, 'Club/Mace', 'Melee', '💪 8', '16', '1g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Club and Mace are among the oldest melee weapons in use: a weighted head on a shaft, designed to crush and break rather than slice. The mace evolved from the primitive club and remains standard issue in many military and religious orders. Modern versions use a reinforced shaft and a heavy head for maximum impact.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (28, 'Combat Knife', 'Melee, Hurled', '💪 6, 🏃 6', '12', '1g', '2026-08-13T21:26:27.294759+00:00', '💪, 🏃', '💪, 🏃', '["Modern", "SciFi"]'::jsonb, 'The Combat Knife is a purpose-built survival and close-combat tool, often regarded as the ultimate field sidearm. It features an eight-inch blade—one edge straight, the other serrated—and a six-inch grip that houses a compact digital compass, self-adjusting for local gravity and capable of displaying positional coordinates. The grip also contains a spool of high-tensile line, emergency rations, a distress beacon, and a small compartment for toxins or other supplies.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (29, 'Crossbow', 'Shot', '👁️ 6', 'n/a', '3g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Crossbow has evolved into a high-performance weapon built from advanced materials, with a prod and mechanism that deliver far greater force than historical designs. Modern versions typically include an integrated bolt magazine and auto-draw system, allowing a bolt to be fired every round without manual spanning. The magazine holds up to twenty bolts and can be loaded with a variety of bolt types.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (30, 'Crystal Guitar', 'Melee', '💪 8', '16', '6g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Crystal Guitar is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (31, 'Crystal Thrower', 'Shot', '👁️ 10', NULL, '10g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Crystal Thrower
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (32, 'Cyber Talons', 'Melee', '💪 6', '12', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["SciFi"]'::jsonb, 'Cyber Talons are cybernetic implants that extend from the fingers rather than from the back of the hand, offering claw damage and grip enhancement.', '', False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (33, 'Dagger', 'Melee, Hurled', '💪 4, 🏃 4', '8', '5s', '2026-08-13T21:26:27.294759+00:00', '💪, 🏃', '💪, 💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Dagger is a short, double-edged blade prized for concealability and lethality at close range. It has long been the weapon of choice for assassins, thieves, and anyone who needs a blade that can be hidden until the last moment. When coated or envenomed, the dagger becomes a one-strike tool of quiet elimination.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (34, 'Disk Cannon', 'Shot', '👁️12', NULL, '10g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Disk Cannon is a heavy weapon that fires spinning metal disks at high velocity, capable of inflicting severe damage in trained hands. Its massive recoil makes it difficult to control without support; it is typically used with a hip-mounted firing arm that braces the weapon. Without the arm (or an equivalent hard-point mount), the operator suffers a significant attack penalty.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (35, 'Disk Pistol', 'Shot', '👁️ 6', NULL, '3g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Disk Pistol is a compact sidearm that fires small spinning disks, commonly issued to military and security personnel who need a concealable sidearm. It is small enough to be hidden under a coat or in a holster and delivers solid damage at close range. The main drawback is its distinctive report—a harsh metallic scrape that is difficult to silence and easy to recognize.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (36, 'Disk Rifle', 'Shot', '👁️ 10', NULL, '7g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Disk Rifle is the standard-issue long arm for many military forces, firing heavier spinning disks than the disk pistol and at greater range. It is approximately three feet long and incorporates a folding shoulder stock; deploying the stock is important for accuracy, and firing without it (or without a hard-point mount) incurs an attack penalty.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (37, 'Dragon Slayer Spear', 'Melee, Hurled', '💪 12, 🏃 12', '24', '9g', '2026-08-13T21:26:27.294759+00:00', '💪, 🏃', '💪, 🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Dragon Slayer Spear is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (38, 'Energy Dagger', 'Melee, Hurled', '💪 6, 🏃 6', '12', '2g', '2026-08-13T21:26:27.294759+00:00', '💪, 🏃', '💪, 🏃', '["Modern", "SciFi"]'::jsonb, 'Energy Dagger
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (39, 'Executioner’s Axe', 'Melee', '💪 12', '24', '8g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Executioner’s Axe is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (40, 'Eye-Laser', 'Shot', '👁️ 6', NULL, '6g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'This laser is implanted in the patient’s head next to an eye. The laser follows all of the user’s eye movements (using targeting computer technology), and is highly accurate. It inflicts only 8L dual damage (see *EM, systems, weapons)* vs normal targets. When used against close stationary items (i.e., to cut) the two barrels slide together forming one beam with a 10M cutting ability. In this form, the beam length is limited to two feet and may not function as a weapon.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (41, 'Flail', 'Melee', '💪 6', '12', '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Flail is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (42, 'Flame Lance', 'Melee', '💪 10', '20', '12g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["SciFi"]'::jsonb, 'Flame Lance
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (43, 'Focus Blade', 'Melee', '💪 8', '16', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Focus Blade is a foot-long black cylinder with a deep red gem set in one end. The cylinder is semi-opaque, containing a solid core of pure black. The red stone seems to be the focus point, from which a blade of up to five feet may be extended, coruscating in the user’s signature color.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (44, 'Force Gauntlet', 'Melee', '💪 6', '12', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Modern", "SciFi"]'::jsonb, 'The Force Gauntlet is a flexible metal glove fitted with a built-in repulsor field that amplifies the force of each strike. When the gauntlet contacts a target, the field triggers, adding significant impact to what would otherwise be a normal punch. The result is a substantial boost to unarmed damage, making the gauntlet a popular choice for brawlers and close-quarters specialists.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (45, 'Gas-Beetle', 'Hurled', '🏃 8', NULL, '2g', '2026-08-13T21:26:27.294759+00:00', '🏃', '🏃', '["SciFi"]'::jsonb, 'Gas-Beetles are biotech organisms that resemble beetles with large gas-filled sacs beneath their wing cases. When directed, they scurry into an area and release their sacs in a burst of noxious gas; the effect is similar to a gas grenade. Victims who fail the relevant check are incapacitated, choking and retching for a number of rounds equal to their failure.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (46, 'Geomantic Staff', 'Melee', '💪 10', '20', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Geomantic Staff
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (47, 'Giant Maul', 'Melee', '💪 12', '24', '10g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Giant Maul is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (48, 'Glaive', 'Melee', '💪 10', '20', '6g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Glaive is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (50, 'Grasp-Glove', 'Melee', '💪 8', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'This squid-like animal slips over the user’s hand (or hand-like appendage), and constricts its wet inner muscles around the user’s forearm.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (51, 'Great Axe', 'Melee', '💪 8', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Great Axe is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (52, 'Grenade Launcher, Underbarrel', 'Shot', '👁️ 12', NULL, '6g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Underbarrel Grenade Launcher, sometimes called a “thumper”, is a compact tube that mounts beneath the barrel of a carbine or larger weapon. A second trigger allows the operator to fire grenades without switching weapons, and the launcher holds up to five rounds. Reloading the magazine is a complete action, so operators must choose when to top off with care.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (53, 'Guard Beetles', 'Hurled', '🏃 8', NULL, '3g', '2026-08-13T21:26:27.294759+00:00', '🏃', '🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'These small squat beetles are a little over an inch in diameter. The listed price will purchase ten beetles, and a small sac of black puffball seeds. Spike beetles enjoy a symbiotic relationship with puffball plants in which the beetles eat the plant''s leaves. In return, spike beetles valiantly guard the plant''s fragile fallen seeds.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (54, 'Halberd', 'Melee', '💪 8', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Halberd is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (55, 'Hand Axe', 'Melee, Hurled', '💪 4, 🏃 4', '8', '2g', '2026-08-13T21:26:27.294759+00:00', '💪, 🏃', '💪, 🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Hand Axe is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (56, 'Hand X-Bow', 'Shot', '👁️ 6', NULL, '2g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Hand X-Bow is a compact crossbow with a pistol grip, designed to fire small metal darts with considerable force from a one-handed frame. It is equipped with an auto-draw mechanism so that the string is spanned automatically after each shot, allowing rapid follow-up fire. Darts can be poison-treated or fitted with special tips in the same way as arrows.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (57, 'Heavy Crossbow', 'Shot', '👁️ 8', 'n/a', '5g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Heavy Crossbow is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (58, 'Heavy Flail', 'Melee', '💪 10', '20', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Heavy Flail is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (59, 'Homing Disc', 'Hurled', '🏃 8', NULL, '4g', '2026-08-13T21:26:27.294759+00:00', '🏃', '🏃', '["SciFi"]'::jsonb, 'The Homing Disc is an advanced throwing weapon that combines the principle of a boomerang with homing and anti-grav technology. The disc is gripped through finger holes in the center and thrown like a discus. A built-in homing device and anti-grav unit automatically returns the disc to the wielder’s holster once it comes to a complete stop (i.e., hits its target or stops sliding after a miss).
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (60, 'Hydro Flamer', 'Shot', '👁️ 12', NULL, '8g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Hydro Flamer projects a thin stream of liquid fuel that ignites upon release, creating a short-ranged cone of fire. The stream can reach several squares, and the fuel includes its own oxidizer, so the weapon functions even in vacuum or other oxygen-poor environments. Damage is highest against the first target in the stream and falls off for subsequent targets in the path.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (61, 'Improvised', 'Melee', '💪 4', '8', 'X', '2026-08-13T21:26:27.294759+00:00', '💪-1d', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Improvised is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (62, 'Inferno Blade', 'Melee', '💪 10', '20', '6g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["SciFi"]'::jsonb, 'Inferno Blade
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (63, 'Javelin-Sword', 'Melee, Shot', '💪 8, 👁️ 6', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪, 👁️', '💪, 👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Javelin-Sword is a hybrid weapon that appears to be a standard blade but conceals a single-shot projectile launcher in the hilt. Opponents who mistake it for an ordinary sword often pay with their lives when a javelin-like bolt is driven from the tip by an integrated mass driver. The blade itself is unaffected by the bolt’s presence or absence and always functions as a sword.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (64, 'Laser Blade', 'Melee', '💪 8', '16', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["SciFi"]'::jsonb, 'The Laser Blade is a sword that projects a blade of coherent light from the hilt, adjustable in length from zero to about three feet. An interference grid contains and shapes the beam, allowing it to cut through most materials with ease. The weapon is a favorite of duelists and special operations personnel who need a compact, devastating melee option.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (65, 'Light Crossbow', 'Shot', '👁️ 4', 'n/a', '2g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Light Crossbow is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (66, 'Living Bow', 'Shot', '👁️ 8', NULL, '5g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Living Bow
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (67, 'Longsword', 'Melee', '💪 6', '12', '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Longsword is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (68, 'Mace (Heavy)', 'Melee', '💪 8', '16', '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Mace (Heavy) is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (69, 'Magazine Bow', 'Shot', '👁️ 8', NULL, '4g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Magazine Bow is an advanced bow that integrates an arrow-storage system into the grip, similar in principle to magazine-fed sidearms. When the bow is drawn to full arch, the store feeds a pre-notched arrow into place, allowing a skilled user to loose two standard arrows per round. The magazine can hold up to fifty arrows in as many as five selected types.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (70, 'Microgrenade Launcher', 'Shot', '👁️ 12', NULL, '10g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'Despite the name “micro,” the Microgrenade Launcher is a large, shoulder-mounted system that fires compact grenades in volume.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (71, 'Missile Launcher', 'Shot', '👁️12', NULL, '14g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Missile Launcher is a shoulder-fired tube that accepts a variety of missile types for long-range, high-yield strikes. When purchased, it typically comes with two standard explosive missiles; additional or specialized missiles are bought separately. The launcher''s main advantage is a small protective field that shields the operator''s hand and arm during launch, reducing backblast and debris injury.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (72, 'Morningstar', 'Melee', '💪 10', '20', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Morningstar is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (73, 'Nano-Blade', 'Melee, Hurled', '💪 6, 🏃 6', '12', '5g', '2026-08-13T21:26:27.294759+00:00', '💪, 🏃', '💪, 🏃', '["SciFi"]'::jsonb, 'Nano-Blade
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (74, 'Needler', 'Shot', '👁️ 6', NULL, '4g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Needler is a small, cone-shaped creature which affixes itself to any desired spot on its user’s body. Upon command, the creature will spit out tiny, razor-sharp needlers. If a needler causes wounding damage, it will burrow beneath the flesh and head for the victim’s heart. This causes 6L additional Dmg each round unless cut out (for additional Dmg equal to all taken so far). Medtechs can remove a needler on a roll equal to the number of rounds the needler has been burrowing. An individual with first aid needs roll equal to all Dmg taken so far in order to remove the needler.', '', False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (75, 'Neon Skateboard', 'Melee', '💪 6', '12', '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Neon Skateboard is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (76, 'Nuke', 'Melee', '💪 12', '24', '1g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Nuke is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (77, 'Phase Rifle', 'Shot', '👁️ 10', NULL, '8g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'Phase Rifle
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (78, 'Pike', 'Melee', '💪 10', '20', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Pike is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (79, 'Pipe Wrench', 'Melee', '💪 8', '16', '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Pipe Wrench is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (80, 'Plasma Gauntlets', 'Melee', '💪 8', '16', '5g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["SciFi"]'::jsonb, 'Plasma Gauntlets
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (81, 'Plasma Sword', 'Melee', '💪 8', '16', '7g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["SciFi"]'::jsonb, 'The Plasma Sword projects a three-foot blade of superheated plasma contained by a magnetized field. Anything that contacts the blade is seared instantly, making it one of the most destructive melee weapons in use.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (82, 'Polearm', 'Melee', '💪 8', '16', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Polearm is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (83, 'Pulse Laser Cannon', 'Shot', '👁️12', NULL, '14g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Pulse Laser Cannon is the heaviest application of pulse-laser technology, firing a thick, sustained beam that can inflict massive damage. The weapon is typically hip-fired due to its size and recoil, and the report is near-deafening—stealth is not an option. It is used by heavy weapons teams and vehicle gunners who need to destroy hardened targets or suppress large areas.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (84, 'Pulse Laser Carbine', 'Shot', '👁️ 8', NULL, '7g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Pulse Laser Carbine is a heavier, more powerful version of the pulse pistol, offering better range and damage in a package that remains compact enough for scouts and mobile troops. It is a favorite of units that need to move fast while still delivering serious energy-weapon firepower. The carbine balances portability with output, making it a common choice for forward observers, scouts, and special operations.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (85, 'Pulse Laser Pistol', 'Shot', '👁️ 6', NULL, '4g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'Small, compact and deadly, pulse pistols are relatively quiet (although the excitation of air molecules from the beam’s passage makes a soft “pop” sound), pulse pistols are excellent weapons for covert operatives and assassins. Legitimate uses include officers’ side-arms and weapons for security guards.', '', False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (86, 'Pulse Laser Rifle', 'Shot', '👁️ 10', NULL, '8g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Pulse Laser Rifle is issued to veteran and elite units, offering higher energy output and range than the pulse pistol or carbine. The stronger beam produces a louder report, making the rifle a poor choice for covert work but an excellent one for open engagement. It has become a standard armament for many professional and military forces.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (87, 'Quad Launcher', 'Shot', '👁️12', NULL, '15g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Quad Launcher is a shoulder-mounted weapon that holds four missiles and requires a hard point for mounting. The operator can fire missiles one at a time, in pairs, or all four in a single salvo. Missile types and effects vary; see ammunition rules for options. When multiple missiles are fired, resolve the attack as for a single shot but multiply wounding damage by the number of missiles that hit.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (88, 'Quad-Disk Cannon', 'Shot', '👁️12', NULL, '14g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Quad-Disk Cannon is a four-barrel variant of the disk cannon, firing all four barrels at once to deliver devastating damage in a single salvo. Like the single-barrel version, it is used with a hip-mounted firing arm or hard-point mount; without it, the operator suffers an attack penalty due to recoil and weight.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (89, 'Quarterstaff', 'Melee', '💪 4', '8', '1g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Quarterstaff is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (90, 'Rage Axe', 'Melee', '💪 12', '24', '6g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Rage Axe
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (91, 'Red Whip', 'Melee', '💪 6', NULL, '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Red Whip
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (92, 'Reinforced Bite', 'Melee', '💪 6', NULL, '0s', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Modern", "SciFi"]'::jsonb, 'During this operation two hydraulic units are set into the jaw on each side. This gives the jaw \+1c Dmg when the bite attack is used.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (93, 'Return-Sickle', 'Hurled', '🏃 6', NULL, '3g', '2026-08-13T21:26:27.294759+00:00', '🏃', '🏃', '["SciFi"]'::jsonb, 'The Return-Sickle is a small, S-shaped throwing weapon that folds into an L-shape for storage. Once it strikes or misses a target, an integrated anti-grav field traces its flight path and returns it to the wielder, who can catch it easily. The weapon can typically be drawn, thrown, and retrieved in a single attack action.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (94, 'Rift Blade', 'Melee', '💪 8', '16', '7g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Rift Blade
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (95, 'Rotary Plasma Gun', 'Shot', '👁️12', NULL, '16g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'The Rotary Plasma Gun mounts six barrels that spin as they fire, each spitting a mass of white-hot plasma. The barrels are cooled by a liquid nitrogen jacket. The weapon is supplied by a plasma precipitator pack (see equipment); the same pack can power a plasma sword or other plasma devices.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (96, 'Scimitar', 'Melee', '💪 6', '12', '3g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Scimitar is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (97, 'Seeker Rifle', 'Shot', '👁️ 10', NULL, '9g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Seeker Rifle is a slender, long-barreled weapon that fires small guided projectiles capable of curving around corners and over obstacles to strike targets that would be protected from line-of-sight fire. The projectiles are less destructive than full seeker missiles but share the same homing principle, making the rifle ideal for engaging foes in cover or behind partial concealment.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (98, 'Serrated Maul', 'Melee', '💪12', '28', '4g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Serrated Maul is a fearsome two-handed pole weapon, nearly seven feet from end to end, that combines the reach of a spear with the cutting power of multiple blades. The head is a mass of barbs, flanges, and edges designed to cut and tear rather than simply pierce. It is favored by warriors who want to dominate reach and leave lasting wounds.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (99, 'Shadow Orb', 'Shot', '👁️ 8', NULL, '4g', '2026-08-13T21:26:27.294759+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Shadow Orb
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (100, 'Short Sword', 'Melee', '💪 4', '8', '1g', '2026-08-13T21:26:27.294759+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Short Sword is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (101, 'Shoulder-Blades', 'Melee', '💪 6', NULL, '3g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Modern", "SciFi"]'::jsonb, 'Shoulder-Blades are semi-circular blades that are partially implanted in the patient’s shoulder or leg. The blades are made of an ultra-light alloy, and are equipped with a tracking system (much like a targeting computer \- see *EM, tech equipment*).
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (102, 'Shredder Cannon', 'Melee, Shot', '💪 8, 👁️12', '16', '15g', '2026-08-13T21:26:27.389133+00:00', '💪, 👁️', '💪, 👁️', '["Modern", "SciFi"]'::jsonb, 'The Shredder Cannon is a two-handed weapon that fires spinning crescents of metal, related in principle to disk weapons but optimized for shredding and area damage. It is durable and bulky; in a pinch it can be used as a club in melee, dealing set damage with the same attack roll as when fired. Operators favor it for the gruesome wounds and psychological impact it creates.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (103, 'Sickle', 'Melee', '💪 4', '8', '1g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Sickle is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (104, 'Siege Fist', 'Melee', '💪 8', '16', '8g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Modern", "SciFi"]'::jsonb, 'This massive appendage is designed to do maximum punch damage. During the operation, the patient’s forearm is removed and the cyber fist is attached in its place.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (105, 'Siege Hammer', 'Melee', '💪 12', '24', '10g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Siege Hammer is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (106, 'Silenced Plasma Pistol', 'Shot', '👁️ 6', NULL, '5g', '2026-08-13T21:26:27.389133+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'Silenced Plasma Pistol
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (107, 'Sonic Disrupter', 'Shot', '👁️12', NULL, '9g', '2026-08-13T21:26:27.389133+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'A sonic disrupter sets up atomic-level vibrations in solid objects, which causes molecular bonds to break down and matter to literally shake apart. The device was designed for use against fortifications (walls, doors, bulk heads, etc.) and terrain obstacles (trees, boulders, etc.) but is gaining popularity with the Guild marines for use against heavily armored opponents, and light vehicles.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (108, 'Sonic Sword', 'Melee', '💪 8', '16', '6g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["SciFi"]'::jsonb, 'The Sonic Sword appears as a small hand grip until activated, when three prongs at the base generate a vibrating field of air molecules that extends about three feet. The blade damages targets by disrupting their molecular structure. It can also be used against stationary obstacles—walls, doors—by holding the blade in contact; the weapon inflicts cumulative damage each round until the object is destroyed, though the object may explode when broken, dealing damage based on its AR.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (109, 'Spear', 'Melee, Hurled', '💪 6, 🏃 6', '12', '2g', '2026-08-13T21:26:27.389133+00:00', '💪, 🏃', '💪, 🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Spear has changed little in principle since its earliest use: a long shaft with a pointed head, for thrusting and throwing. Modern versions use durable alloys for the shaft and head, making them nearly unbreakable under normal use. They remain a staple on low-tech and frontier worlds, used for hunting, militia duty, and combat.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (110, 'Spore Blaster', 'Shot', '👁️ 8', NULL, '6g', '2026-08-13T21:26:27.389133+00:00', '👁️', '👁️', '["SciFi"]'::jsonb, 'Spore Blaster
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (111, 'Strangle Spear', 'Hurled', '🏃 8', NULL, '3g', '2026-08-13T21:26:27.389133+00:00', '🏃', '🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'To an outside observer, this weapon would resemble a poorly carved wooden spear. In reality, when this living weapon hits its target (inflicting 10L damage), it immediately transforms into a sinuous, ropy strand which will attempt to loop around and strangle its victim. This strangling attack is made at the spear’s rating (10/16/1). If it hits, it will use its Str (16 or 8M) vs the victim''s FR in an attempt to strangle the victim. If successful the victim begins suffocating. Victims may attempt to break free each round (Str check vs the spear''s Str of 16 (8M)).|', '', False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (112, 'Stun', 'Shot', '👁️ 8', NULL, '1g', '2026-08-13T21:26:27.389133+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'The Stun is a compact handheld weapon that uses focused sound waves to overwhelm the nervous system and knock targets unconscious. Attack rolls are made normally; effect is resolved against the target''s WP rather than AR. If the roll exceeds the target''s WP, the victim falls unconscious for a number of rounds equal to the margin of success. Beings who cannot hear or who wear protective headgear receive a bonus to their WP when resisting.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (113, 'Sun-Blades', 'Melee', '💪 6', '12', '7g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Sun-Blades are a paired set of exotic blades forged from a metal that naturally stores solar energy and releases it as a powerful shock when triggered. The blades are detachable and can be left in direct sunlight to recharge; after at least a half-hour in full sun, each blade can deliver one stun discharge. The wielder releases the stored energy by depressing a hidden stud, and the target must resist or be stunned for a number of rounds equal to the failure.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (114, 'Sword', 'Melee', '💪 8', '16', '3g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Sword is the standard melee blade in most systems: approximately three feet of blade on a one-handed grip, used for cutting and thrusting. It has been the sidearm of choice for militant orders and soldiers across countless worlds. Swords are especially valued in confined or sensitive environments—such as ship-boarding—where ranged or explosive weapons would risk collateral damage.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (115, 'Tail Spikes', 'Melee', '💪 6', '12', '2g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Some species remove the tail at birth; others retain it. Those who keep their tails can benefit from the tail spike implant.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (116, 'Talon-Spear', 'Melee, Hurled', '💪 8, 🏃 8', '16', '3g', '2026-08-13T21:26:27.389133+00:00', '💪, 🏃', '💪, 🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Talon-Spear is a five-foot pole with three spring-loaded talons at one end. A rope or cord can be attached for retrieval after throwing.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (117, 'Thermite Grenades', 'Hurled', '🏃 12', NULL, '3g', '2026-08-13T21:26:27.389133+00:00', '🏃', '🏃', '["Modern", "SciFi"]'::jsonb, 'Thermite Grenades
