INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (119, 'Throw', 'Hurled', '🏃 4', NULL, '0s', '2026-08-13T21:26:27.389133+00:00', '🏃', '🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Throw
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (120, 'Throw Object', 'Hurled', '🏃 4', 'n/a', 'X', '2026-08-13T21:26:27.389133+00:00', '🏃', '💪-1d', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Throw Object is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
