INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (122, 'Throwing Knives (set)', 'Hurled', '🏃 4', 'n/a', '2g', '2026-08-13T21:26:27.389133+00:00', '🏃', '🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Throwing Knives (set) is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (123, 'Toothed Dagger', 'Melee, Hurled', '💪 6, 🏃 6', '12', '2g', '2026-08-13T21:26:27.389133+00:00', '💪, 🏃', '💪, 🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Toothed Dagger is a long-bladed knife with one sharp edge and one deliberately jagged edge, designed to tear and saw as well as slice. It is the close-combat equivalent of a standard dagger in many warrior cultures, favored by experts who know how to maximize its unique profile. In skilled hands, the weapon can inflict severe and messy wounds.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (124, 'Tower Crossbow', 'Shot', '👁️ 12', 'n/a', '8g', '2026-08-13T21:26:27.389133+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Tower Crossbow is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (125, 'Trident', 'Melee, Hurled', '💪 6, 🏃 6', '12', '3g', '2026-08-13T21:26:27.389133+00:00', '💪, 🏃', '💪, 🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Trident is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (126, 'Trip-Stave', 'Melee', '💪 8', '16', '2g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Trip-Stave is a two-handed pole weapon designed for control and versatility rather than raw lethality. It allows the wielder to choose before each attack whether to trip, disarm, or wound an opponent, making it a favorite of duelists and tactical fighters who prefer to dictate the flow of combat.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (127, 'Vampiric Claws', 'Melee', '💪 6', '12', '5g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Vampiric Claws
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (128, 'Venom Injector Carbine', 'Shot', '👁️ 8', NULL, '8g', '2026-08-13T21:26:27.389133+00:00', '👁️', '👁️', '["Modern", "SciFi"]'::jsonb, 'Venom Injector Carbine
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (129, 'Venom Tail', 'Melee', '💪 8', '16', '5g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Venom Tail is a large muscular implant that sits on the abdomen and has three stinger-tipped tails. The tails can attack one opponent per round—in front, to the sides, or behind the host. Each stinger can hold up to ten doses of poison; natural poison sacs can be added for an extra cost to manufacture paralysis poison at a set rate. With the Venom Tail, the host can strike from multiple angles and deliver toxins in close combat.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (130, 'Void Sphere', 'Hurled', '🏃 8', NULL, '8g', '2026-08-13T21:26:27.389133+00:00', '🏃', '🏃', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Void Sphere is a tiny hollow sphere, about the size of a cherry, that opens a localized rift when activated and thrown. A channeler must expend two power points to activate the sphere, then may throw it at a target. On impact, the sphere shatters and implodes, creating a brief wash of energy that seems to tear a small hole in reality itself.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (131, 'Void Staff', 'Melee', '💪 8', '16', '6g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Void Staff
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (132, 'War-Crescent', 'Melee', '💪12', '28', '4g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The War-Crescent is a two-handed weapon in the shape of a broad metal crescent, studded with additional points and edges. It is a symbol of martial tradition in many cultures and is taught in dedicated schools of combat. The blades and flanges can be used to hook, slice, pin, or restrain—some styles emphasize non-lethal control, while others focus on lethal close combat.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (133, 'Warhammer', 'Melee', '💪 8', '16', '5g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Warhammer is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (134, 'WarPick', 'Melee', '💪 6', '12', '2g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'WarPick is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (135, 'Warrior Claws', 'Melee', '💪 6', '12', '3g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Warrior Claws are three metal blades mounted on a forearm harness and extending from between the fingers. The blades can be retracted into the sheath at will so the wearer can use the hand normally when not fighting. When extended, they deliver serious damage in close combat and can slash or stab in a single motion.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (136, 'WarScythe', 'Melee', '💪 12', '24', '8g', '2026-08-13T21:26:27.389133+00:00', '💪', '💪', '["Medieval", "Modern", "SciFi"]'::jsonb, 'WarScythe is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (137, 'Web-Ball', 'Hurled', '🏃 8', NULL, '1g', '2026-08-13T21:26:27.389133+00:00', '🏃', '🏃', '["Modern", "SciFi"]'::jsonb, 'The Web-Ball looks like a six-inch diameter sponge and functions as a defensive weapon. Sponge balls may be tossed or rolled. When tossed, the sponge ball explodes if it hits something; when rolled, the sponge ball waits until it comes to a stop to explode.
INSERT INTO public."weapons" ("id", "name", "type", "requirement", "max_block", "cost", "created_at", "atk", "dmg", "genres", "notes", "pic", "is_guildspace_locked") VALUES (138, 'Web-Launcher', 'Shot', '👁️ 8', NULL, '7g', '2026-08-13T21:26:27.389133+00:00', '👁️', '👁️', '["Medieval", "Modern", "SciFi"]'::jsonb, 'This creature is a long worm, which forms a cocoon-like home on its host’s body. Upon command, the slinger flings out a ball of sticky, web like material.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (1, 'Arcane Wardsuit', '💪 S', '🧥S', '👣7', '20g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Arcane Wardsuit merges medieval craftsmanship with cutting-edge technology, featuring a latticework of alloyed steel plates reinforced with translucent synthetic alloys that glow with a faint, pulsating cerulean light. The suit’s contours are streamlined, with articulated joints sheathed in adaptive polymers that shift texture and opacity in response to environmental threats. A low hum resonates from embedded arcane circuitry, generating a shimmering barrier of refracted energy that flickers like liquid starlight around the wearer’s form.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (2, 'Archaic Partial A', '💪 8', '🧥8', '👣10', '2g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Archaic Partial A combines two pieces for moderate coverage—for example breastplate and helmet, or vambraces and greaves. The wearer gains protection to vital areas (torso and head, or arms and legs) while staying mobile. Metal, leather, and padding are used in traditional construction; each piece can be styled to match the other for a cohesive look.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (3, 'Archaic Partial G', '💪 12', '🧥12', '👣8', '4g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Archaic Partial G combines three pieces for substantial coverage—typically breastplate, helmet, and vambraces. The torso, head, and forearms are protected, leaving the legs relatively free for movement. This loadout is common among front-line fighters who want strong upper-body and head protection while retaining leg mobility for advancing or retreating.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (4, 'Archaic Partial H', '💪 10', '🧥10', '👣9', '4g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Archaic Partial H is full partial coverage: breastplate, greaves, helmet, and vambraces together. Every major body region is protected—torso, head, arms, and legs—while the armor remains partial rather than a full suit. This is the heaviest and most protective option in the archaic partial category, favored by heavy infantry and those who expect sustained melee.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (5, 'Archaic Partial L', '💪 6', '🧥6', '👣11', '1g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Archaic Partial L is the lightest coverage in this category, consisting of a single light piece such as vambraces or greaves. It offers minimal and maximum mobility while protecting one body region—either the forearms or the shins and knees. Crafted from metal strips or plates on leather or cloth backing, with padding for comfort, it is the choice for those who want a touch of traditional protection without committing to a full partial loadout.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (6, 'Artisan Plate', '💪 12', '🧥12', '👣8', '8g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Artisan Plate is a heavy, full-coverage suit of plate armor reserved for ceremonial use or when maximum protection is required. Like Artisan Ring-Mail, each suit is a unique work of art, with a long and detailed history. Because plate severely limits movement and sensation, suits often incorporate small patches of ring-mail at key points to preserve some hearing and awareness—yet even then, the wearer''s senses are heavily restricted.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (7, 'Artisan Ring-Mail', '💪 8', '🧥8', '👣10', '3g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'Artisan Ring-Mail is a masterwork suit of full-body armor, crafted using traditional methods with no high technology, yet offering remarkable protection and aesthetic detail. Weighing in at a moderate burden for its coverage, this armor consists of large, interlocked metal rings—often called ring-mail—that deflect most physical attacks while leaving enough gaps for the wearer to retain keen environmental awareness and tactile sensitivity. Each ring is hand-forged and inscribed with minute images and abstract patterns, making every suit a unique work of art with its own history.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (10, 'Assault Armor', '💪 10', '🧥10', '👣9', '4g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Assault Armor is a heavier variant of marine-grade armor, built for hazardous duties such as direct assault, ship boarding, and high-intensity combat. It combines robust plating with integrated systems that enhance survivability and effectiveness in confined or hostile environments. The suit is sealed against contaminants and includes lighting, medical support, and strength augmentation to help the wearer push through resistance and complete objectives.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (11, 'Banded Armor', '💪 10', '🧥10', '👣9', '5g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A fusion of medieval craftsmanship and futuristic engineering, this armor combines overlapping steel bands with sleek, titanium-infused alloys, forming a layered lattice that hugs the wearer’s contours like a second skin. The chestplate features a central embossment of interlocking gears, their edges etched with faintly luminescent circuitry that pulses in sync with the wearer’s movements, while the limbs are sheathed in segmented plates reinforced with carbon-fiber weave, allowing for fluid motion without sacrificing durability. A faint, iridescent haze clings to the surface, as if the metal itself hums with latent energy, and the hauberk beneath is woven from a synthetic filament that repels corrosion and dissipates heat, leaving the wearer cool even in the throes of combat.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (12, 'Bio-Tech', '💪 8', '🧥8', '👣10', '4g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bio-Tech Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (13, 'Blaze', '💪 8', '🧥8', '👣10', '4g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Blaze Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (14, 'Bloodweave', '💪 6', '🧥6', '👣11', '3g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Bloodweave Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (15, 'Brigandine', '💪 8', '🧥8', '👣10', '3g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A hybrid of medieval craftsmanship and futuristic engineering, the Brigandine merges interlocking steel plates with a lattice of carbon-fiber reinforced polymer, its surface etched with faintly glowing circuitry that pulses in sync with the wearer''s movements. The cuirass conforms to the body with a second-skin precision, its overlapping scales layered over a flexible exoskeleton of nano-armor that shifts hue in response to environmental threats, while articulated joints allow for fluid motion without sacrificing defense. A faint, prismatic aura hovers just above the armor''s surface, as if the metal itself is alive, and the shoulder guards taper into sleek, aerodynamic curves reminiscent of both heraldic crests and modern aerospace design.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (16, 'Carapace Armor', '💪 S', '🧥S', '👣7', '5g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Carapace Armor is among the most effective bio-armors: a living shell with tendons and mantles along its length that open like a clam shell and then close snugly around the wearer. It is heavy, but its protection rivals that of top-tier marine armor. The shell seals itself airtight and filters outside air to maintain a breathable environment; the front is left clear so vision is unimpeded. Bio-engineers can produce carapaces tailored to different species by special arrangement and exchange of valuable materials.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (17, 'Chain Shirt', '💪 8', '🧥8', '👣10', '2g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Chain Shirt is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (18, 'Cyber A', '💪 8', '🧥8', '👣10', '7g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'Cyber A adds torso and both forearms to the facial plating. The wearer has chest or back coverage (or one major torso surface), full facial armor, and both forearms plated. This moderate coverage protects the core and arms while leaving the upper arms and legs unarmored. The plating is integrated across regions for a cohesive cyber look.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (19, 'Cyber G', '💪 12', '🧥12', '👣8', '6g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'Cyber G extends coverage to full torso (chest and back), full facial armor, and both arms in full—forearm and upper arm on each side. The wearer''s core, head, and arms are fully protected by cyber plating; only the legs remain unarmored. This substantial loadout is for those who expect heavy contact in the upper body and want maximum arm and torso protection.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (20, 'Cyber H', '💪 10', '🧥10', '👣9', '6g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'Cyber H is full-body partial cyber armor: torso (chest and back), facial plating, both arms (forearm and upper arm each), and both legs (thigh, knee, and shin each). Every major region is covered with integrated cyber plating, creating a complete partial suit. The armor is still classified as partial rather than full suit armor but represents the maximum coverage available in the cyber armor line.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (21, 'Cyber L', '💪 6', '🧥6', '👣11', '3g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'Cyber L is minimal cyber armor coverage: facial plating plus one forearm. The face is protected by gleaming metallic half-face armor, often used alongside cyber-eyes and inscribed with runes or symbolic images. One forearm is fully plated and integrated with the user''s cybernetic framework. Together they offer light partial protection for those who want a visible cyber look without heavy coverage.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (22, 'Denim Battle Vest', '💪 6', '🧥6', '👣11', '1g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Denim Battle Vest is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (23, 'Dragon Scale Armor', '💪 S', '🧥S', '👣7', '12g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Dragon Scale Armor is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (24, 'Ethereal', '💪 6', '🧥6', '👣11', '3g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Ethereal Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (25, 'Expedition Armor', '💪 12', '🧥12', '👣8', '4g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Expedition Armor is heavier than standard trooper armor and is typically issued to infantry who expect heavy firepower or prolonged resistance. Door gunners, vehicle crews, and dismounted troops in contested zones often wear this style for the extra protection and the ability to operate for extended periods with integrated nutrition and medical support. It offers a balance between mobility and durability for sustained operations.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (26, 'Field Plate', '💪 12', '🧥12', '👣8', '7g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Field Plate is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (27, 'Flak', '💪 6', '🧥6', '👣11', '2g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'Flak is a generic term for infantry body armor consisting of metal, ceramic, or plastic plates sewn or bonded into a vest and pants. Lightweight and affordable, it is widely used by infantry, irregulars, and anyone who needs basic protection without the cost or weight of full tactical armor. The plates distribute impact and stop or reduce penetration from small arms and fragmentation.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (28, 'Full Plate', '💪 S', '🧥S', '👣7', '10g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Full Plate is a masterwork of interlocking steel plates, meticulously forged by ancient blacksmiths to form a seamless second skin. Every joint is reinforced with riveted girders, and the polished surface reflects the wearer''s resolve, turning the armor into a mobile fortress of unyielding defiance.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (29, 'Fury', '💪 S', '🧥S', '👣7', '16g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Fury Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (30, 'Gaia', '💪 6', '🧥6', '👣11', '3g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Gaia Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (31, 'Gambeson', '💪 6', '🧥6', '👣11', '2g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Gambeson is a quilted textile masterpiece, woven from dense layers of linen and wool to absorb the force of blows. Its padded construction offers a surprising balance of flexibility and protection, resembling a second layer of flesh that moves in harmony with the wearer''s every motion.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (32, 'Geomantic', '💪 12', '🧥12', '👣8', '8g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Geomantic Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (33, 'Glowweave Robe', '💪 6', '🧥6', '👣11', '2g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Glowweave Robe is engineered with high-durability composite materials for reliable field operations.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (34, 'Half-Plate', '💪 12', '🧥12', '👣8', '6g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Half-Plate combines the resilience of plate armor with the agility of chainmail, featuring reinforced plates on the torso and limbs while leaving the arms and legs clad in supple leather. The design strikes a balance between defense and mobility, its angular contours suggesting both strength and calculated restraint.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (35, 'Hardened Riot Exo-Suit', '💪 12', '🧥12', '👣8', '8g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Hardened Riot Exo-Suit is a fusion of cybernetic engineering and tactical armor, featuring a skeletal framework of carbon fiber and titanium alloy. Its surface is covered in a reactive polymer that shifts color in response to environmental threats, while integrated plating offers protection against both ballistic and energy-based attacks.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (36, 'Heavy Laminar', '💪 12', '🧥12', '👣8', '6g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Heavy Laminar is constructed from overlapping layers of tempered steel and reinforced leather, bound together with braided steel cords. The armor''s layered design distributes impact across its surface, creating a visual effect of rippling metal that seems to absorb blows rather than resist them.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (37, 'Hide Armor', '💪 8', '🧥8', '👣10', '1g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Hide Armor is crafted from the thick, supple hides of large beasts, expertly tanned and layered to form a flexible yet durable defense. Its natural texture and muted sheen give it a rugged, primal appearance, blending seamlessly with the wilderness.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (38, 'Husk Armor', '💪 12', '🧥12', '👣8', '4g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Husk Armor is made from the dried husks of genetically engineered seed vessels. After the seeds are released, the remaining brownish husk is roughly the size of an adult humanoid and can be tailored to fit different species. Like pod armor, it is a form of bio-armor that relies on grown rather than forged materials. The husk is lightweight for its coverage and provides good protection against impacts and abrasion, though it lacks the self-sealing and regeneration of living carapace or vine armor.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (39, 'Juggernaut Armor', '💪 S', '🧥S', '👣7', '8g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Juggernaut Armor is heavily armored, power-assisted, and built to dominate the battlefield. The wearer becomes a walking engine of destruction, capable of absorbing and shrugging off attacks that would disable lighter suits. Multiple hardpoints, joint locks, and strength enhancers allow the operator to carry heavy weapons and close with the enemy under fire, while sealed systems and integrated lighting support operations in any environment.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (40, 'Lamellar Armor', '💪 8', '🧥8', '👣10', '3g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Lamellar Armor consists of overlapping rectangular plates sewn onto a sturdy backing, offering a balance of mobility and protection. The intricate arrangement of the scales mimics the armor of reptiles, exuding a sense of ancient craftsmanship and tactical precision.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (41, 'Leaf Armor', '💪 6', '🧥6', '👣11', '3g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Leaf Armor is a symbiotic vine that grows on the host''s body and must be watered occasionally. The vine produces layers of tough, shingle-like leaves that absorb damage and slough off when struck, then regrow within days. A single plant produces enough leaves to last through an extended adventure, making it a renewable form of protection favored by those who can maintain a symbiotic relationship with the organism.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (42, 'Leather Jacket', '💪 6', '🧥6', '👣11', '1g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A Leather Jacket is a lightweight, form-fitting armor made from cured animal hide, reinforced with stitching and metal tips for added durability. Its supple surface conforms to the wearer''s body, providing a practical and versatile layer of defense.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (43, 'Marine Armor', '💪 8', '🧥8', '👣10', '5g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Marine Armor is heavy, well-defended suit armor and is widely recognized as the standard protection for elite marine forces. It combines full coverage with an internal environment, strength enhancers, and a full suite of tactical systems so that marines can fight in vacuum, in atmosphere, or in contaminated zones without compromise. The suit is sealed, climate-controlled, and built to withstand the rigors of ship-to-ship and planetary operations.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (44, 'Mithril Mail', '💪 S', '🧥S', '👣7', '15g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Mithril Mail is a rare and lustrous armor forged from the ethereal silver-gray metal known as mithril. Its lightweight yet impossibly strong threads shimmer faintly, as if woven from starlight itself, making it a coveted treasure among warriors.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (45, 'Obsidian Carapace', '💪 S', '🧥S', '👣7', '15g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'The Obsidian Carapace is a seamless, matte-black exosuit forged from hyper-dense volcanic glass and reinforced with a lattice of nano-fibers, its surface etched with faint, iridescent circuitry that pulses with a low, ambient glow. The armor’s contours mimic the jagged, organic geometry of a predator’s skeleton, with overlapping plates that shift subtly under movement, as if alive, while its joints are lined with a slick, non-reflective polymer that repels both physical impact and energy discharges. In dim light, faint fractal patterns shimmer across its surface, resembling trapped lightning, and the air around it hums with a static charge, as though the suit itself is a conduit for latent power.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (46, 'Padded Cloth', '💪 6', '🧥6', '👣11', '5s', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A dense, quilted matrix of interwoven synthetic fibers and reinforced polymer weaves, the Padded Cloth armor forms a second skin over the wearer’s body, its surface etched with micro-channel patterns that dissipate heat and moisture. In medieval contexts, it mimics layered wool and linen, stitched with geometric precision to balance flexibility and impact absorption; in sci-fi iterations, it adopts a sleek, matte-black polymer with embedded neural接口 nodes that adapt to the user’s biomechanics. Its seams are reinforced with a translucent, honeycomb-like resin, giving it a faintly iridescent sheen under bright light, while discreet utility pockets along the torso and limbs suggest a focus on practicality over ornamentation.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (47, 'Plate Harness', '💪 10', '🧥10', '👣9', '5g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A fusion of medieval craftsmanship and futuristic engineering, the Plate Harness is a sleek, angular exoskeleton forged from blackened titanium-infused steel, its surface etched with intricate, glowing circuitry that pulses faintly with an inner light. The armor’s overlapping plates mimic traditional chainmail in texture but are reinforced with lightweight nanocomposite plating, while a reinforced, helmet-like visor curves over the wearer’s face, its polished surface reflecting ambient light like a mirror. Articulated joints allow fluid movement, and along the spine runs a serpentine conduit of faintly bioluminescent alloy, suggesting both protection and an unseen, adaptive technological interface.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (48, 'Pod Armor', '💪 8', '🧥8', '👣10', '4g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Pod Armor is grown from enormous seed-pods produced by a dedicated plant. The pods are cultivated to the size of the intended wearer (humanoid or other species) and the cost typically covers the plant itself, which continuously produces pods. Once a pod is picked and used, it withers and becomes useless as armor after roughly one adventure (about two to four weeks). A healthy plant always has at least one pod ready for harvest, so users can rotate pods as needed.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (49, 'Power Frame', '💪 10', '🧥12', '👣8', '10g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'A Power Frame is a military version of the industrial power lifters used to move cargo and heavy objects. It resembles an oversized humanoid framework with large mechanical claws and a partially armored roll cage to protect the operator. In addition to lifting and carrying, it is fitted with compensators, strength enhancers, joint locks, and multiple hardpoints, making it suitable for combat engineering, breaching, and heavy-weapons deployment.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (50, 'Riot Gear', '💪 10', '🧥10', '👣9', '4g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A hybrid of modular plating and reinforced synthetic fabric, Riot Gear merges angular, overlapping plates of darkened alloy with sleek, ergonomic contours that hug the wearer’s form. Embedded within the armor’s surface are faintly glowing etchings of circuitry, their patterns shifting subtly in response to movement, while reinforced polymer panels flex like second skin under impact. The helmet’s visor integrates a translucent, holographic display that projects tactical data and environmental hazards, its edges lined with a faint, pulsating aura of adaptive camouflage that blurs the wearer’s outline against chaotic backdrops.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (51, 'Samurai Armor', '💪 12', '🧥12', '👣8', '7g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A fusion of traditional craftsmanship and cutting-edge materials, this armor combines layered steel plates with reinforced polymer composites, molded into a sleek, ergonomic silhouette. The helmet features a narrow, angular visor reminiscent of samurai kabuto, framed by glowing circuitry that pulses with a faint, neon-blue aura, while articulated joints are sheathed in seamless cerametal alloys that shimmer under light. A pair of curved, blade-like pauldrons extend from the shoulders, etched with intricate wave patterns that seem to ripple subtly, as if caught between solid matter and liquid energy.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (52, 'Scale Mail', '💪 8', '🧥8', '👣10', '3g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Overlapping plates of reinforced polymer and interwoven carbon fiber form a second-skin exosuit, each scale etched with micro-grooves that channel kinetic energy away from the wearer. The armor’s surface shimmers with a faint iridescence, as if coated in liquid metal that shifts hue with movement, while embedded filaments of adaptive nanofiber tighten or loosen dynamically to balance flexibility and impact resistance. A faint, pulsating glow emanates from the joints, suggesting latent reactive properties that might deflect projectiles or dissipate heat, though its full potential remains enigmatic.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (53, 'Scout Armor', '💪 6', '🧥6', '👣11', '3g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Scout Armor is a lightweight suit of advanced plate affixed to a durable body suit, designed for reconnaissance, flanking, and operations where stealth and mobility matter. It is constructed with a personal stealth net that significantly increases the wearer''s ability to avoid detection—granting a substantial bonus to Dexterity-based rolls opposed by Awareness when moving unseen. Compensators, internal hard point, and full communications and macrovisor support are included, along with jump-pack and oxygenator options for extended and vertical operations.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (54, 'Space Suit', '💪 4', '🧥4', '👣12', '4g', '2026-08-13T21:26:27.615956+00:00', '["Modern", "SciFi"]'::jsonb, 'Space Suits are compact and efficient, fully spaceworthy and capable of sustaining the wearer in vacuum and hostile atmospheres. They are of minimal use in direct combat due to limited armor and mobility, but they are essential for extravehicular activity, emergency egress, and operations in airless or toxic environments. Integrated systems include sealing, internal environment, illuminator, macrovisor with star-light and star-lamp enhancement, and ultralock boot kit for secure footing.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (55, 'Spectre', '💪 8', '🧥8', '👣10', '4g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Spectre Armor Kit
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (56, 'Spider Armor', '💪 8', '🧥8', '👣10', '5g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Spider Armor is one of the most unusual forms of bio-armor: thousands of tiny arachnids swarm over the wearer''s body, interlocking their thorny legs to form a living layer that covers every exposed surface. When some spiders are destroyed by impacts or projectiles, the semi-sentient swarm quickly redistributes to close gaps, restoring full coverage. The spiders also act as a living cargo net, holding the wearer''s gear in place, and they bite unauthorized individuals who attempt to touch the wearer or their belongings—inflicting moderate damage and an irritating itch. The armor can be disconcerting for those unaccustomed to it, but it provides resilient, self-repairing protection and built-in security for carried items.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (57, 'Spider Enhanced', '💪 10', '🧥10', '👣9', '7g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'For an additional cost, larger warrior spiders can be purchased to upgrade Spider Armor. The enhanced swarm provides higher armor rating (20 AR). The bite of the larger spiders is more potent, causing greater damage to anyone who attempts to pilfer the wearer''s belongings. These larger spiders can recognize the host''s close associates and will not attack them if they judge the associate''s intentions to be honorable.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (58, 'Spiked Armor', '💪 10', '🧥10', '👣9', '5g', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Spiked Armor is a fearsome defensive gear adorned with jagged, protruding spikes along its surface. Designed to deter close combat attacks, its intimidating appearance radiates menace, making the wearer a formidable opponent on the battlefield.', NULL, False) ON CONFLICT DO NOTHING;
