INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (64, 'Trooper Armor', '💪 8', '🧥8', '👣10', '4g', '2026-08-13T21:26:27.615956+00:00', '["SciFi"]'::jsonb, 'Trooper Armor is the standard personal armor for infantry across many forces. It consists of rigid plates over a micro-mesh body suit and includes a full-head helmet. It offers solid protection against small arms and fragments while remaining relatively light and mobile. One external hard point allows for mission-specific gear; integrated targeting computer, communicator kit, and oxygenator support sustained operations in atmosphere or in thin-air environments.
INSERT INTO public."armor" ("id", "name", "requirement", "ar", "mr", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (65, 'Unarmored', '💪 4', '🧥4', '👣12', '0s', '2026-08-13T21:26:27.615956+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'No Armor, Clothing, or other non-armor gear', NULL, False) ON CONFLICT DO NOTHING;
