INSERT INTO public."shields" ("id", "name", "requirement", "max_block", "mr", "notes", "cost", "created_at", "genres", "is_guildspace_locked") VALUES (1, 'Heater Shield', '💪 6', '🛡️16', '👣-1', 'The heater shield is a large, roughly triangular shield most commonly associated with knights and other archaic heavy troop types. It provides a moderate amount of protection across a broad front, covering the torso and upper leg when held in line, and is often used in formation or for mounted combat. Its flat or gently curved face can bear heraldry or unit markings.
INSERT INTO public."shields" ("id", "name", "requirement", "max_block", "mr", "notes", "cost", "created_at", "genres", "is_guildspace_locked") VALUES (2, 'Kite Shield', '💪 8', '🛡️20', '👣-2', 'Long tapered shield, excellent for infantry formations.', '4g', '2026-08-13T21:26:27.809384+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, False) ON CONFLICT DO NOTHING;
INSERT INTO public."shields" ("id", "name", "requirement", "max_block", "mr", "notes", "cost", "created_at", "genres", "is_guildspace_locked") VALUES (3, 'Power Shield', '💪 6', '🛡️16', '👣-1', 'The Power Shield is a physical shield enhanced with an ultralock assembly so it can be securely attached to the user''s arm, leaving the hand free when needed. A charged ionic field around the shield disperses or attenuates energy-weapon hits, while a micro-repulsor field diverts or reduces the energy of kinetic attacks. The result is a hybrid defense that combines the reliability of a physical barrier with active countermeasures.
INSERT INTO public."shields" ("id", "name", "requirement", "max_block", "mr", "notes", "cost", "created_at", "genres", "is_guildspace_locked") VALUES (4, 'Round Shield', '💪 4', '🛡️12', '👣0', 'Mid-sized wooden shield, classic adventurer gear.', '2g', '2026-08-13T21:26:27.809384+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, False) ON CONFLICT DO NOTHING;
INSERT INTO public."shields" ("id", "name", "requirement", "max_block", "mr", "notes", "cost", "created_at", "genres", "is_guildspace_locked") VALUES (5, 'Siege Wall Shield', '💪 12', '🛡️28', '👣-4', 'Oversized heavy wood-and-iron shield, used in sieges.', '10g', '2026-08-13T21:26:27.809384+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, False) ON CONFLICT DO NOTHING;
INSERT INTO public."shields" ("id", "name", "requirement", "max_block", "mr", "notes", "cost", "created_at", "genres", "is_guildspace_locked") VALUES (6, 'Tower Shield', '💪 10', '🛡️24', '👣-3', 'Tower shields are large, bulky, and relatively clumsy, rarely carried by modern mobile forces. On low-tech worlds and in historical warfare, they character used to form shield walls and to protect against massed archery and thrown weapons. A single bearer can shelter behind one while advancing or holding a position, trading mobility for maximum frontal coverage.
