INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (102, '🛠️ Tools & Equipment', 'Hammer (small)', '4s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A compact hammer with a short, sturdy shaft and a rounded head, designed for precision work. The handle is wrapped in coarse leather for a secure grip, while the head is forged from tempered steel, gleaming with a faint metallic sheen.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (103, '🛠️ Tools & Equipment', 'Hammer (wooden, tent)', '2s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A stout, hand-carved hammer with a broad, slightly worn wooden head and a short, sturdy handle wrapped in braided rope. Its design suggests it was meant for driving stakes into the earth rather than combat, though it could serve in a pinch.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (104, '🛠️ Tools & Equipment', 'Mallet (wood)', '2s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A simple, hand-carved wooden mallet with a smooth, rounded head and a shaft wrapped in braided rope. Its natural grain patterns suggest it was crafted by skilled hands, ideal for gentle yet firm strikes.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (105, '🛠️ Tools & Equipment', 'Nails (25)', '1s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A bundle of twenty-five slender, pointed nails, their surfaces polished to a sharp edge. Each nail is forged from durable iron, with a slight curvature at the tip to ensure a firm grip in wood or metal.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (106, '🛠️ Tools & Equipment', 'Net (10 ft)', '8s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A 10-foot diameter net woven from thick, water-resistant fibers, its knots reinforced with metal rings to prevent fraying. The mesh is taut and evenly spaced, ideal for entangling prey or securing cargo during transport.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (107, '🛠️ Tools & Equipment', 'Pickaxe', '7s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A robust pickaxe with a long, reinforced shaft and a heavy, chisel-like head. The head is forged from hardened steel, featuring a pointed tip and two sturdy prongs for breaking through stone and rock.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (108, '🛠️ Tools & Equipment', 'Rope (50 ft hemp)', '5s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A 50-foot length of braided hemp rope, its fibers tightly twisted to form a strong, flexible cord. The rope bears the faint scent of aged wood and has been treated with a natural preservative to resist rot and wear.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (109, '🛠️ Tools & Equipment', 'Rope (50 ft silk)', '2g', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A 50-foot length of finely woven silk rope, lightweight yet incredibly strong. Its surface is smooth and lustrous, with a faint sheen that catches the light, making it ideal for climbing, securing, or intricate tasks.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (110, '🛠️ Tools & Equipment', 'Saw (hand)', '6s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A compact, hand-operated saw with a narrow blade of hardened steel, featuring a series of fine, closely spaced teeth that gleam under the light. The wooden handle is wrapped in leather, providing a secure grip even when wet or slick with sap.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (111, '🛠️ Tools & Equipment', 'Shovel (iron)', '6s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A robust iron shovel with a broad, curved blade and a thick, reinforced shaft. The blade shows signs of use, with minor dents and scratches, while the handle is wrapped in leather for a secure grip during laborious tasks.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (112, '🛠️ Tools & Equipment', 'Skillet (iron)', '4s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A heavy iron skillet with a thick, curved handle and a broad, concave surface, ideal for frying or searing over an open flame. Its darkened patina and reinforced edges suggest years of use, though it remains sturdy and well-balanced in the hand.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (113, '🛠️ Tools & Equipment', 'Spikes (iron, 10)', '4s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'Ten iron spikes, each sharpened to a fine point and forged with a slight curvature for easier penetration. The spikes are arranged in a neat bundle, their surfaces darkened by repeated exposure to fire and weather.', NULL, False) ON CONFLICT DO NOTHING;
INSERT INTO public."gear" ("id", "category", "name", "cost", "created_at", "genres", "notes", "pic", "is_guildspace_locked") VALUES (114, '🛠️ Tools & Equipment', 'Waterscoop Ladle', '1s', '2026-08-13T21:26:28.086535+00:00', '["Medieval", "Modern", "SciFi"]'::jsonb, 'A long-handled ladle with a wide, shallow bowl and a series of small, evenly spaced holes along the rim, designed for efficiently transferring liquid without spillage. The wooden shaft is smooth and worn, while the metal bowl is dented but still functional.', NULL, False) ON CONFLICT DO NOTHING;
